+package llmsdk
+
+import (
+	"encoding/base64"
+	"encoding/json"
+	"errors"
+	"os"
+	"path/filepath"
+	"strings"
+)
+
+type Role string
+
+const (
+	RoleSystem    Role = "SYSTEM"
+	RoleUser      Role = "USER"
+	RoleAssistant Role = "ASSISTANT"
+	RoleTool      Role = "TOOL"
+	RoleDeveloper Role = "DEVELOPER"
+)
+
+type ContentKind string
+
+const (
+	ContentText            ContentKind = "TEXT"
+	ContentImage           ContentKind = "IMAGE"
+	ContentAudio           ContentKind = "AUDIO"
+	ContentDocument        ContentKind = "DOCUMENT"
+	ContentToolCall        ContentKind = "TOOL_CALL"
+	ContentToolResult      ContentKind = "TOOL_RESULT"
+	ContentThinking        ContentKind = "THINKING"
+	ContentRedactedThinking ContentKind = "REDACTED_THINKING"
+)
+
+type Message struct {
+	Role       Role          `json:"role"`
+	Content    []ContentPart `json:"content"`
+	Name       *string       `json:"name,omitempty"`
+	ToolCallID *string       `json:"tool_call_id,omitempty"`
+}
+
+func SystemMessage(text string) Message { return Message{Role: RoleSystem, Content: []ContentPart{TextPart(text)}} }
+func UserMessage(text string) Message   { return Message{Role: RoleUser, Content: []ContentPart{TextPart(text)}} }
+func AssistantMessage(text string) Message {
+	return Message{Role: RoleAssistant, Content: []ContentPart{TextPart(text)}}
+}
+
+func ToolResultMessage(toolCallID string, content any, isError bool) Message {
+	return Message{
+		Role:       RoleTool,
+		ToolCallID: &toolCallID,
+		Content: []ContentPart{{
+			Kind: ContentToolResult,
+			ToolResult: &ToolResultData{
+				ToolCallID: toolCallID,
+				Content:    content,
+				IsError:    isError,
+			},
+		}},
+	}
+}
+
+func (m Message) Text() string {
+	var b strings.Builder
+	for _, p := range m.Content {
+		if strings.EqualFold(string(p.Kind), string(ContentText)) && p.Text != nil {
+			b.WriteString(*p.Text)
+		}
+	}
+	return b.String()
+}
+
+type ContentPart struct {
+	Kind       ContentKind     `json:"kind"`
+	Text       *string         `json:"text,omitempty"`
+	Image      *ImageData      `json:"image,omitempty"`
+	Audio      *AudioData      `json:"audio,omitempty"`
+	Document   *DocumentData   `json:"document,omitempty"`
+	ToolCall   *ToolCallData   `json:"tool_call,omitempty"`
+	ToolResult *ToolResultData `json:"tool_result,omitempty"`
+	Thinking   *ThinkingData   `json:"thinking,omitempty"`
+}
+
+func TextPart(text string) ContentPart { return ContentPart{Kind: ContentText, Text: &text} }
+
+type ImageData struct {
+	URL       *string `json:"url,omitempty"`
+	Data      []byte  `json:"data,omitempty"`
+	MediaType *string `json:"media_type,omitempty"`
+	Detail    *string `json:"detail,omitempty"`
+}
+
+func (img ImageData) ResolveDataFromURLIfLocal() (ImageData, error) {
+	if img.URL == nil {
+		return img, nil
+	}
+	u := strings.TrimSpace(*img.URL)
+	if u == "" {
+		return img, nil
+	}
+	if strings.HasPrefix(u, "http://") || strings.HasPrefix(u, "https://") || strings.HasPrefix(u, "data:") {
+		return img, nil
+	}
+	if strings.HasPrefix(u, "~") {
+		home, err := os.UserHomeDir()
+		if err != nil {
+			return img, err
+		}
+		u = filepath.Join(home, strings.TrimPrefix(u, "~"))
+	}
+	if !(strings.HasPrefix(u, "/") || strings.HasPrefix(u, "./") || strings.HasPrefix(u, "../")) {
+		return img, nil
+	}
+	b, err := os.ReadFile(u)
+	if err != nil {
+		return img, err
+	}
+	img.Data = b
+	img.URL = nil
+	if img.MediaType == nil {
+		mt := inferMediaTypeFromExt(u)
+		img.MediaType = &mt
+	}
+	return img, nil
+}
+
+func (img ImageData) DataURI() (string, error) {
+	if len(img.Data) == 0 {
+		return "", errors.New("image has no data")
+	}
+	mt := "image/png"
+	if img.MediaType != nil && *img.MediaType != "" {
+		mt = *img.MediaType
+	}
+	return "data:" + mt + ";base64," + base64.StdEncoding.EncodeToString(img.Data), nil
+}
+
+type AudioData struct {
+	URL       *string `json:"url,omitempty"`
+	Data      []byte  `json:"data,omitempty"`
+	MediaType *string `json:"media_type,omitempty"`
+}
+
+type DocumentData struct {
+	URL       *string `json:"url,omitempty"`
+	Data      []byte  `json:"data,omitempty"`
+	MediaType *string `json:"media_type,omitempty"`
+	FileName  *string `json:"file_name,omitempty"`
+}
+
+type ToolCallData struct {
+	ID        string `json:"id"`
+	Name      string `json:"name"`
+	Arguments any    `json:"arguments"`
+	Type      string `json:"type"`
+}
+
+type ToolResultData struct {
+	ToolCallID      string `json:"tool_call_id"`
+	Content         any    `json:"content"`
+	IsError         bool   `json:"is_error"`
+	ImageData       []byte `json:"image_data,omitempty"`
+	ImageMediaType  *string `json:"image_media_type,omitempty"`
+}
+
+type ThinkingData struct {
+	Text      string  `json:"text"`
+	Signature *string `json:"signature,omitempty"`
+	Redacted  bool    `json:"redacted"`
+}
+
+type Tool struct {
+	Name        string          `json:"name"`
+	Description string          `json:"description"`
+	Parameters  json.RawMessage `json:"parameters"`
+	Execute     ToolExecutor    `json:"-"`
+}
+
+type ToolExecutor func(ctx ToolContext) (any, error)
+
+type ToolContext struct {
+	ToolCallID string
+	Arguments  map[string]any
+	Messages   []Message
+}
+
+type ToolChoice struct {
+	Mode     string  `json:"mode"`
+	ToolName *string `json:"tool_name,omitempty"`
+}
+
+type ResponseFormat struct {
+	Type       string          `json:"type"` // "text", "json", "json_schema"
+	JSONSchema json.RawMessage `json:"json_schema,omitempty"`
+	Strict     bool            `json:"strict"`
+}
+
+type Request struct {
+	Model           string                 `json:"model"`
+	Messages        []Message              `json:"messages"`
+	Provider        *string                `json:"provider,omitempty"`
+	Tools           []Tool                 `json:"tools,omitempty"`
+	ToolChoice      *ToolChoice            `json:"tool_choice,omitempty"`
+	ResponseFormat  *ResponseFormat        `json:"response_format,omitempty"`
+	Temperature     *float64               `json:"temperature,omitempty"`
+	TopP            *float64               `json:"top_p,omitempty"`
+	MaxTokens       *int                   `json:"max_tokens,omitempty"`
+	StopSequences   []string               `json:"stop_sequences,omitempty"`
+	ReasoningEffort *string                `json:"reasoning_effort,omitempty"`
+	Metadata        map[string]string      `json:"metadata,omitempty"`
+	ProviderOptions map[string]any         `json:"provider_options,omitempty"`
+}
+
+type FinishReason struct {
+	Reason string  `json:"reason"`
+	Raw    *string `json:"raw,omitempty"`
+}
+
+type Usage struct {
+	InputTokens      int    `json:"input_tokens"`
+	OutputTokens     int    `json:"output_tokens"`
+	ReasoningTokens  *int   `json:"reasoning_tokens,omitempty"`
+	CacheReadTokens  *int   `json:"cache_read_tokens,omitempty"`
+	CacheWriteTokens *int   `json:"cache_write_tokens,omitempty"`
+	Raw              any    `json:"raw,omitempty"`
+}
+
+func (u Usage) TotalTokens() int { return u.InputTokens + u.OutputTokens }
+
+func (u Usage) Add(v Usage) Usage {
+	out := Usage{
+		InputTokens:  u.InputTokens + v.InputTokens,
+		OutputTokens: u.OutputTokens + v.OutputTokens,
+	}
+	out.ReasoningTokens = addOptInt(u.ReasoningTokens, v.ReasoningTokens)
+	out.CacheReadTokens = addOptInt(u.CacheReadTokens, v.CacheReadTokens)
+	out.CacheWriteTokens = addOptInt(u.CacheWriteTokens, v.CacheWriteTokens)
+	return out
+}
+
+func addOptInt(a, b *int) *int {
+	if a == nil && b == nil {
+		return nil
+	}
+	av := 0
+	if a != nil {
+		av = *a
+	}
+	bv := 0
+	if b != nil {
+		bv = *b
+	}
+	s := av + bv
+	return &s
+}
+
+type Warning struct {
+	Message string  `json:"message"`
+	Code    *string `json:"code,omitempty"`
+}
+
+type RateLimitInfo struct {
+	RequestsRemaining *int    `json:"requests_remaining,omitempty"`
+	RequestsLimit     *int    `json:"requests_limit,omitempty"`
+	TokensRemaining   *int    `json:"tokens_remaining,omitempty"`
+	TokensLimit       *int    `json:"tokens_limit,omitempty"`
+	ResetAt           *string `json:"reset_at,omitempty"`
+}
+
+type Response struct {
+	ID           string        `json:"id"`
+	Model        string        `json:"model"`
+	Provider     string        `json:"provider"`
+	Message      Message       `json:"message"`
+	FinishReason FinishReason  `json:"finish_reason"`
+	Usage        Usage         `json:"usage"`
+	Raw          any           `json:"raw,omitempty"`
+	Warnings     []Warning     `json:"warnings,omitempty"`
+	RateLimit    *RateLimitInfo `json:"rate_limit,omitempty"`
+}
+
+func (r Response) Text() string { return r.Message.Text() }
+
+func (r Response) ToolCalls() []ToolCall {
+	var out []ToolCall
+	for _, part := range r.Message.Content {
+		if part.Kind == ContentToolCall && part.ToolCall != nil {
+			args := map[string]any{}
+			rawArgs := ""
+			switch v := part.ToolCall.Arguments.(type) {
+			case map[string]any:
+				args = v
+			case json.RawMessage:
+				_ = json.Unmarshal(v, &args)
+				rawArgs = string(v)
+			case string:
+				rawArgs = v
+				_ = json.Unmarshal([]byte(v), &args)
+			default:
+				b, _ := json.Marshal(v)
+				rawArgs = string(b)
+				_ = json.Unmarshal(b, &args)
+			}
+			out = append(out, ToolCall{ID: part.ToolCall.ID, Name: part.ToolCall.Name, Arguments: args, RawArguments: &rawArgs})
+		}
+	}
+	return out
+}
+
+func (r Response) Reasoning() *string {
+	var b strings.Builder
+	for _, part := range r.Message.Content {
+		if (part.Kind == ContentThinking || part.Kind == ContentRedactedThinking) && part.Thinking != nil && !part.Thinking.Redacted {
+			b.WriteString(part.Thinking.Text)
+		}
+	}
+	s := b.String()
+	if s == "" {
+		return nil
+	}
+	return &s
+}
+
+type ToolCall struct {
+	ID          string         `json:"id"`
+	Name        string         `json:"name"`
+	Arguments   map[string]any `json:"arguments"`
+	RawArguments *string       `json:"raw_arguments,omitempty"`
+}
+
+type ToolResult struct {
+	ToolCallID string `json:"tool_call_id"`
+	Content    any    `json:"content"`
+	IsError    bool   `json:"is_error"`
+}
+
+type StreamEventType string
+
+const (
+	StreamStart       StreamEventType = "STREAM_START"
+	TextStart         StreamEventType = "TEXT_START"
+	TextDelta         StreamEventType = "TEXT_DELTA"
+	TextEnd           StreamEventType = "TEXT_END"
+	ReasoningStart    StreamEventType = "REASONING_START"
+	ReasoningDelta    StreamEventType = "REASONING_DELTA"
+	ReasoningEnd      StreamEventType = "REASONING_END"
+	ToolCallStart     StreamEventType = "TOOL_CALL_START"
+	ToolCallDelta     StreamEventType = "TOOL_CALL_DELTA"
+	ToolCallEnd       StreamEventType = "TOOL_CALL_END"
+	StreamFinish      StreamEventType = "FINISH"
+	StreamError       StreamEventType = "ERROR"
+	ProviderEvent     StreamEventType = "PROVIDER_EVENT"
+)
+
+type StreamEvent struct {
+	Type            StreamEventType `json:"type"`
+	Delta           *string         `json:"delta,omitempty"`
+	TextID          *string         `json:"text_id,omitempty"`
+	ReasoningDelta  *string         `json:"reasoning_delta,omitempty"`
+	ToolCall        *ToolCall       `json:"tool_call,omitempty"`
+	FinishReason    *FinishReason   `json:"finish_reason,omitempty"`
+	Usage           *Usage          `json:"usage,omitempty"`
+	Response        *Response       `json:"response,omitempty"`
+	Error           *SDKError       `json:"error,omitempty"`
+	Raw             any             `json:"raw,omitempty"`
+}
+
+func inferMediaTypeFromExt(path string) string {
+	ext := strings.ToLower(filepath.Ext(path))
+	switch ext {
+	case ".png":
+		return "image/png"
+	case ".jpg", ".jpeg":
+		return "image/jpeg"
+	case ".gif":
+		return "image/gif"
+	case ".webp":
+		return "image/webp"
+	default:
+		return "image/png"
+	}
+}
+
*** End Patch

