+package llmsdk
+
+import (
+	"context"
+	"errors"
+	"os"
+	"sync"
+)
+
+type ProviderAdapter interface {
+	Name() string
+	Complete(ctx context.Context, req Request) (Response, error)
+	Stream(ctx context.Context, req Request) (EventStream, error)
+}
+
+type CompleteFunc func(ctx context.Context, req Request) (Response, error)
+type StreamFunc func(ctx context.Context, req Request) (EventStream, error)
+
+type CompleteMiddleware func(ctx context.Context, req Request, next CompleteFunc) (Response, error)
+type StreamMiddleware func(ctx context.Context, req Request, next StreamFunc) (EventStream, error)
+
+type Client struct {
+	providers        map[string]ProviderAdapter
+	defaultProvider  *string
+	completeMW       []CompleteMiddleware
+	streamMW         []StreamMiddleware
+}
+
+func NewClient(providers map[string]ProviderAdapter, defaultProvider *string) *Client {
+	cp := map[string]ProviderAdapter{}
+	for k, v := range providers {
+		cp[k] = v
+	}
+	return &Client{
+		providers:       cp,
+		defaultProvider: defaultProvider,
+	}
+}
+
+func (c *Client) WithCompleteMiddleware(mw ...CompleteMiddleware) *Client {
+	c.completeMW = append(c.completeMW, mw...)
+	return c
+}
+
+func (c *Client) WithStreamMiddleware(mw ...StreamMiddleware) *Client {
+	c.streamMW = append(c.streamMW, mw...)
+	return c
+}
+
+func (c *Client) resolveProvider(req Request) (ProviderAdapter, string, error) {
+	var key string
+	if req.Provider != nil && *req.Provider != "" {
+		key = *req.Provider
+	} else if c.defaultProvider != nil && *c.defaultProvider != "" {
+		key = *c.defaultProvider
+	} else {
+		return nil, "", &SDKError{Type: "ConfigurationError", Message: "no provider specified and no default provider configured"}
+	}
+	ad, ok := c.providers[key]
+	if !ok {
+		return nil, "", &SDKError{Type: "ConfigurationError", Message: "provider not configured: " + key}
+	}
+	return ad, key, nil
+}
+
+func (c *Client) Complete(ctx context.Context, req Request) (Response, error) {
+	ad, key, err := c.resolveProvider(req)
+	if err != nil {
+		return Response{}, err
+	}
+	req.Provider = &key
+	base := func(ctx context.Context, req Request) (Response, error) {
+		return ad.Complete(ctx, req)
+	}
+	next := base
+	for i := len(c.completeMW) - 1; i >= 0; i-- {
+		mw := c.completeMW[i]
+		prev := next
+		next = func(ctx context.Context, req Request) (Response, error) {
+			return mw(ctx, req, prev)
+		}
+	}
+	return next(ctx, req)
+}
+
+func (c *Client) Stream(ctx context.Context, req Request) (EventStream, error) {
+	ad, key, err := c.resolveProvider(req)
+	if err != nil {
+		return nil, err
+	}
+	req.Provider = &key
+	base := func(ctx context.Context, req Request) (EventStream, error) {
+		return ad.Stream(ctx, req)
+	}
+	next := base
+	for i := len(c.streamMW) - 1; i >= 0; i-- {
+		mw := c.streamMW[i]
+		prev := next
+		next = func(ctx context.Context, req Request) (EventStream, error) {
+			return mw(ctx, req, prev)
+		}
+	}
+	return next(ctx, req)
+}
+
+func (c *Client) ListModels(provider *string) []ModelInfo {
+	return ListModels(provider)
+}
+
+func (c *Client) GetModelInfo(id string) *ModelInfo { return GetModelInfo(id) }
+
+func (c *Client) DefaultProvider() *string { return c.defaultProvider }
+
+func ClientFromEnv() (*Client, error) {
+	var providers = map[string]ProviderAdapter{}
+	var defaultProvider *string
+
+	if key := os.Getenv("OPENAI_API_KEY"); key != "" {
+		base := os.Getenv("OPENAI_BASE_URL")
+		ad := NewOpenAIAdapter(OpenAIConfig{APIKey: key, BaseURL: base})
+		providers["openai"] = ad
+		if defaultProvider == nil {
+			s := "openai"
+			defaultProvider = &s
+		}
+	}
+	if key := os.Getenv("ANTHROPIC_API_KEY"); key != "" {
+		base := os.Getenv("ANTHROPIC_BASE_URL")
+		ad := NewAnthropicAdapter(AnthropicConfig{APIKey: key, BaseURL: base})
+		providers["anthropic"] = ad
+		if defaultProvider == nil {
+			s := "anthropic"
+			defaultProvider = &s
+		}
+	}
+	if key := os.Getenv("GEMINI_API_KEY"); key != "" {
+		base := os.Getenv("GEMINI_BASE_URL")
+		ad := NewGeminiAdapter(GeminiConfig{APIKey: key, BaseURL: base})
+		providers["gemini"] = ad
+		if defaultProvider == nil {
+			s := "gemini"
+			defaultProvider = &s
+		}
+	}
+
+	if len(providers) == 0 {
+		return nil, &SDKError{Type: "ConfigurationError", Message: "no providers configured from environment"}
+	}
+	return NewClient(providers, defaultProvider), nil
+}
+
+var (
+	defaultClientMu sync.Mutex
+	defaultClient   *Client
+	defaultInitOnce sync.Once
+	defaultInitErr  error
+)
+
+func SetDefaultClient(c *Client) {
+	defaultClientMu.Lock()
+	defer defaultClientMu.Unlock()
+	defaultClient = c
+	defaultInitOnce = sync.Once{}
+	defaultInitErr = nil
+}
+
+func DefaultClient() (*Client, error) {
+	defaultInitOnce.Do(func() {
+		c, err := ClientFromEnv()
+		if err != nil {
+			defaultInitErr = err
+			return
+		}
+		defaultClient = c
+	})
+	defaultClientMu.Lock()
+	defer defaultClientMu.Unlock()
+	if defaultClient == nil {
+		if defaultInitErr != nil {
+			return nil, defaultInitErr
+		}
+		return nil, errors.New("default client not initialized")
+	}
+	return defaultClient, nil
+}
+
