+	defaultInitOnce.Do(func() {
+		c, err := ClientFromEnv()
+		if err != nil {
+			defaultInitErr = err
+			return
+		}
+		defaultClient = c
+	})
+	defaultClientMu.Lock()
+	defer defaultClientMu.Unlock()
+	if defaultClient == nil {
+		if defaultInitErr != nil {
+			return nil, defaultInitErr
+		}
+		return nil, errors.New("default client not initialized")
+	}
