+
+type EventStream interface {
+	Next() (StreamEvent, error) // returns io.EOF at end
+	Close() error
+}
+
+type chanEventStream struct {
+	ctx    context.Context
+	events <-chan StreamEvent
+	errs   <-chan error
+	once   sync.Once
+	closeFn func()
+}
+
+func (s *chanEventStream) Next() (StreamEvent, error) {
+	select {
+	case <-s.ctx.Done():
+		return StreamEvent{}, &SDKError{Type: "AbortError", Message: s.ctx.Err().Error()}
+	case ev, ok := <-s.events:
+		if !ok {
+			select {
+			case err, ok := <-s.errs:
+				if ok && err != nil && !errors.Is(err, io.EOF) {
+					return StreamEvent{}, err
+				}
+			default:
+			}
+			return StreamEvent{}, io.EOF
+		}
+		return ev, nil
+	case err, ok := <-s.errs:
+		if ok && err != nil {
+			return StreamEvent{}, err
+		}
+		return StreamEvent{}, io.EOF
+	}
+}
+
+func (s *chanEventStream) Close() error {
+	s.once.Do(func() {
+		if s.closeFn != nil {
+			s.closeFn()
+		}
+	})
+	return nil
+}
+
+func newChanEventStream(ctx context.Context, events <-chan StreamEvent, errs <-chan error, closeFn func()) EventStream {
+	return &chanEventStream{ctx: ctx, events: events, errs: errs, closeFn: closeFn}
+}
