+type HTTPClient interface {
+	Do(req *http.Request) (*http.Response, error)
+}
+
+func defaultHTTPClient() *http.Client {
+	return &http.Client{Timeout: 120 * time.Second}
+}
+
+func postJSON(ctx context.Context, httpClient HTTPClient, url string, headers map[string]string, body any) (*http.Response, []byte, error) {
+	var buf bytes.Buffer
+	if err := json.NewEncoder(&buf).Encode(body); err != nil {
+		return nil, nil, err
+	}
+	req, err := http.NewRequestWithContext(ctx, http.MethodPost, url, &buf)
+	if err != nil {
+		return nil, nil, err
+	}
+	req.Header.Set("Content-Type", "application/json")
+	for k, v := range headers {
+		req.Header.Set(k, v)
+	}
+	resp, err := httpClient.Do(req)
+	if err != nil {
+		return nil, nil, &SDKError{Type: "NetworkError", Message: err.Error()}
+	}
+	defer func() {
+		// body will be read below; ensure drained for keepalive
+	}()
+	b, err := io.ReadAll(resp.Body)
+	if err != nil {
+		return resp, nil, &SDKError{Type: "NetworkError", Message: err.Error()}
+	}
+	return resp, b, nil
+}
+
+func joinURL(base, path string) string {
+	if base == "" {
+		return path
+	}
+	base = strings.TrimRight(base, "/")
+	path = strings.TrimLeft(path, "/")
+	return base + "/" + path
