+package llmsdk
+
+import (
+	"bufio"
+	"context"
+	"io"
+	"strings"
+)
+
+type sseEvent struct {
+	Event string
+	Data  string
+}
+
+func decodeSSE(ctx context.Context, r io.Reader, out chan<- sseEvent, errCh chan<- error) {
+	defer close(out)
+	defer close(errCh)
+
+	sc := bufio.NewScanner(r)
+	// allow long lines
+	buf := make([]byte, 0, 64*1024)
+	sc.Buffer(buf, 8*1024*1024)
+
+	var curEvent string
+	var dataLines []string
+
+	flush := func() {
+		if curEvent == "" && len(dataLines) == 0 {
+			return
+		}
+		out <- sseEvent{Event: curEvent, Data: strings.Join(dataLines, "\n")}
+		curEvent = ""
+		dataLines = nil
+	}
+
+	for sc.Scan() {
+		select {
+		case <-ctx.Done():
+			errCh <- ctx.Err()
+			return
+		default:
+		}
+		line := sc.Text()
+		if line == "" {
+			flush()
+			continue
+		}
+		if strings.HasPrefix(line, ":") {
+			continue
+		}
+		if strings.HasPrefix(line, "event:") {
+			curEvent = strings.TrimSpace(strings.TrimPrefix(line, "event:"))
+			continue
+		}
+		if strings.HasPrefix(line, "data:") {
+			dataLines = append(dataLines, strings.TrimSpace(strings.TrimPrefix(line, "data:")))
+			continue
+		}
+		// ignore retry:, id:, and unknown fields
+	}
+	if err := sc.Err(); err != nil {
+		errCh <- err
+		return
+	}
+	flush()
+	errCh <- io.EOF
+}
+
