+package llmsdk
+
+import (
+	"context"
+	"encoding/json"
+	"fmt"
+	"io"
+	"net/http"
+	"strings"
+	"sync"
+)
+
+type OpenAIConfig struct {
+	APIKey    string
+	BaseURL   string // includes /v1
+	OrgID     string
+	ProjectID string
+	HTTP      HTTPClient
+}
+
+type OpenAIAdapter struct {
+	cfg    OpenAIConfig
+	client HTTPClient
+}
+
+func NewOpenAIAdapter(cfg OpenAIConfig) *OpenAIAdapter {
+	hc := cfg.HTTP
+	if hc == nil {
+		hc = defaultHTTPClient()
+	}
+	if cfg.BaseURL == "" {
+		cfg.BaseURL = "https://api.openai.com/v1"
+	}
+	return &OpenAIAdapter{cfg: cfg, client: hc}
+}
+
+func (a *OpenAIAdapter) Name() string { return "openai" }
+
+func (a *OpenAIAdapter) Complete(ctx context.Context, req Request) (Response, error) {
+	body, headers, err := a.translateRequest(req, false)
+	if err != nil {
+		return Response{}, err
+	}
+	url := joinURL(a.cfg.BaseURL, "responses")
+	resp, b, err := postJSON(ctx, a.client, url, headers, body)
+	if err != nil {
+		return Response{}, err
+	}
+	if resp.StatusCode < 200 || resp.StatusCode >= 300 {
+		return Response{}, a.translateHTTPError(resp, b)
+	}
+	var raw any
+	_ = json.Unmarshal(b, &raw)
+	return a.translateResponse(raw)
+}
+
+func (a *OpenAIAdapter) Stream(ctx context.Context, req Request) (EventStream, error) {
+	body, headers, err := a.translateRequest(req, true)
+	if err != nil {
+		return nil, err
+	}
+	url := joinURL(a.cfg.BaseURL, "responses")
+
+	// manual request to stream
+	j, err := json.Marshal(body)
+	if err != nil {
+		return nil, err
+	}
+	httpReq, err := http.NewRequestWithContext(ctx, http.MethodPost, url, strings.NewReader(string(j)))
+	if err != nil {
+		return nil, err
+	}
+	httpReq.Header.Set("Content-Type", "application/json")
+	httpReq.Header.Set("Accept", "text/event-stream")
+	for k, v := range headers {
+		httpReq.Header.Set(k, v)
+	}
+
+	resp, err := a.client.Do(httpReq)
+	if err != nil {
+		return nil, &SDKError{Type: "NetworkError", Message: err.Error()}
+	}
+	if resp.StatusCode < 200 || resp.StatusCode >= 300 {
+		b, _ := io.ReadAll(resp.Body)
+		_ = resp.Body.Close()
+		return nil, a.translateHTTPError(resp, b)
+	}
+
+	events := make(chan StreamEvent, 128)
+	errs := make(chan error, 1)
+	streamCtx, cancel := context.WithCancel(ctx)
+
+	go func() {
+		defer cancel()
+		defer resp.Body.Close()
+
+		events <- StreamEvent{Type: StreamStart}
+
+		sseOut := make(chan sseEvent, 64)
+		sseErr := make(chan error, 1)
+		go decodeSSE(streamCtx, resp.Body, sseOut, sseErr)
+
+		type toolAccum struct {
+			id   string
+			name string
+			args strings.Builder
+		}
+		toolAccums := map[string]*toolAccum{}
+		textStarted := map[string]bool{}
+		var textBuf strings.Builder
+
+		for {
+			select {
+			case <-streamCtx.Done():
+				errs <- streamCtx.Err()
+				close(events)
+				return
+			case ev, ok := <-sseOut:
+				if !ok {
+					err := <-sseErr
+					if err == nil {
+						err = io.EOF
+					}
+					errs <- err
+					close(events)
+					return
+				}
+				if strings.TrimSpace(ev.Data) == "" || ev.Data == "[DONE]" {
+					continue
+				}
+				var payload map[string]any
+				if err := json.Unmarshal([]byte(ev.Data), &payload); err != nil {
+					events <- StreamEvent{Type: ProviderEvent, Raw: ev.Data}
+					continue
+				}
+				t, _ := payload["type"].(string)
+				if t == "" {
+					t = ev.Event
+				}
+
+				switch t {
+				case "response.output_text.delta":
+					delta, _ := payload["delta"].(string)
+					itemID, _ := payload["item_id"].(string)
+					if itemID == "" {
+						itemID = "text"
+					}
+					if !textStarted[itemID] {
+						textStarted[itemID] = true
+						id := itemID
+						events <- StreamEvent{Type: TextStart, TextID: &id}
+					}
+					if delta != "" {
+						textBuf.WriteString(delta)
+						d := delta
+						id := itemID
+						events <- StreamEvent{Type: TextDelta, Delta: &d, TextID: &id}
+					}
+				case "response.function_call_arguments.delta":
+					callID, _ := payload["call_id"].(string)
+					if callID == "" {
+						callID, _ = payload["id"].(string)
+					}
+					if callID == "" {
+						callID = "call"
+					}
+					name, _ := payload["name"].(string)
+					delta, _ := payload["delta"].(string)
+					acc, ok := toolAccums[callID]
+					if !ok {
+						acc = &toolAccum{id: callID, name: name}
+						toolAccums[callID] = acc
+						tc := ToolCall{ID: callID, Name: name, Arguments: map[string]any{}}
+						events <- StreamEvent{Type: ToolCallStart, ToolCall: &tc}
+					}
+					if delta != "" {
+						acc.args.WriteString(delta)
+						tc := ToolCall{ID: callID, Name: acc.name, Arguments: map[string]any{}, RawArguments: strPtr(delta)}
+						events <- StreamEvent{Type: ToolCallDelta, ToolCall: &tc}
+					}
+				case "response.output_item.done":
+					// best-effort: if it includes a function call finalization, emit TOOL_CALL_END
+					it, _ := payload["item"].(map[string]any)
+					if it != nil {
+						if typ, _ := it["type"].(string); typ == "function_call" {
+							id, _ := it["id"].(string)
+							name, _ := it["name"].(string)
+							argsStr, _ := it["arguments"].(string)
+							args := map[string]any{}
+							_ = json.Unmarshal([]byte(argsStr), &args)
+							tc := ToolCall{ID: id, Name: name, Arguments: args, RawArguments: &argsStr}
+							events <- StreamEvent{Type: ToolCallEnd, ToolCall: &tc}
+						}
+						if typ, _ := it["type"].(string); typ == "output_text" {
+							itemID, _ := it["id"].(string)
+							if itemID == "" {
+								itemID = "text"
+							}
+							id := itemID
+							events <- StreamEvent{Type: TextEnd, TextID: &id}
+						}
+					}
+				case "response.completed":
+					// payload may be {type, response:{...}}
+					rawResp := any(payload)
+					if r, ok := payload["response"]; ok {
+						rawResp = r
+					}
+					resp, err := a.translateResponse(rawResp)
+					if err != nil {
+						events <- StreamEvent{Type: StreamError, Error: &SDKError{Type: "StreamError", Message: err.Error()}}
+						errs <- err
+						close(events)
+						return
+					}
+					fr := resp.FinishReason
+					u := resp.Usage
+					events <- StreamEvent{Type: StreamFinish, FinishReason: &fr, Usage: &u, Response: &resp}
+				default:
+					events <- StreamEvent{Type: ProviderEvent, Raw: payload}
+				}
+			}
+		}
+	}()
+
+	return newChanEventStream(ctx, events, errs, cancel), nil
+}
+
+func strPtr(s string) *string { return &s }
+
+func (a *OpenAIAdapter) translateRequest(req Request, stream bool) (map[string]any, map[string]string, error) {
+	if strings.TrimSpace(req.Model) == "" {
+		return nil, nil, &SDKError{Type: "InvalidRequestError", Message: "model is required"}
+	}
+	instructions := extractInstructions(req.Messages)
+
+	input := []any{}
+	for _, m := range req.Messages {
+		switch m.Role {
+		case RoleSystem, RoleDeveloper:
+			// handled via instructions
+			continue
+		case RoleTool:
+			// translate tool results
+			tcID := ""
+			if m.ToolCallID != nil {
+				tcID = *m.ToolCallID
+			}
+			for _, p := range m.Content {
+				if p.Kind == ContentToolResult && p.ToolResult != nil {
+					out := stringifyJSONish(p.ToolResult.Content)
+					input = append(input, map[string]any{
+						"type":    "function_call_output",
+						"call_id": p.ToolResult.ToolCallID,
+						"output":  out,
+					})
+				}
+			}
+			if tcID != "" {
+				_ = tcID
+			}
+		case RoleUser, RoleAssistant:
+			role := "user"
+			if m.Role == RoleAssistant {
+				role = "assistant"
+			}
+			content := []any{}
+			for _, p := range m.Content {
+				switch p.Kind {
+				case ContentText:
+					if p.Text != nil {
+						typ := "input_text"
+						if role == "assistant" {
+							typ = "output_text"
+						}
+						content = append(content, map[string]any{"type": typ, "text": *p.Text})
+					}
+				case ContentImage:
+					if p.Image == nil {
+						continue
+					}
+					img, err := p.Image.ResolveDataFromURLIfLocal()
+					if err != nil {
+						return nil, nil, err
+					}
+					if img.URL != nil {
+						content = append(content, map[string]any{"type": "input_image", "image_url": *img.URL})
+					} else if len(img.Data) > 0 {
+						uri, err := img.DataURI()
+						if err != nil {
+							return nil, nil, err
+						}
+						content = append(content, map[string]any{"type": "input_image", "image_url": uri})
+					}
+				case ContentToolCall:
+					// tool calls are top-level items in Responses API
+					if p.ToolCall == nil {
+						continue
+					}
+					argStr := ""
+					switch v := p.ToolCall.Arguments.(type) {
+					case string:
+						argStr = v
+					default:
+						b, _ := json.Marshal(v)
+						argStr = string(b)
+					}
+					input = append(input, map[string]any{
+						"type":      "function_call",
+						"id":        p.ToolCall.ID,
+						"name":      p.ToolCall.Name,
+						"arguments": argStr,
+					})
+				default:
+					// ignore unsupported kinds in OpenAI adapter input
+				}
