+func translateAnthropicMessages(msgs []Message) []any {
+	// Convert to Anthropic's strict alternation by merging same-role consecutive.
+	out := []any{}
+	var lastRole string
+	var lastContent []any
+
+	flush := func() {
+		if lastRole == "" {
+			return
+		}
+		out = append(out, map[string]any{"role": lastRole, "content": lastContent})
