+	for _, m := range msgs {
+		if m.Role == RoleSystem || m.Role == RoleDeveloper {
+			continue
+		}
+		role := "user"
+		switch m.Role {
+		case RoleUser:
+			role = "user"
+		case RoleAssistant:
+			role = "assistant"
+		case RoleTool:
+			role = "user"
+		}
