+func encodeBase64(b []byte) string {
+	// json marshaling of []byte already base64-encodes but we need explicit string in Anthropic image source
+	enc := make([]byte, 0, len(b)*2)
+	_ = enc
+	return base64Std(b)
+}
+
+func base64Std(b []byte) string {
+	const table = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
+	var out strings.Builder
+	var val uint
+	var valb int
+	valb = -6
+	for _, c := range b {
+		val = (val << 8) | uint(c)
+		valb += 8
+		for valb >= 0 {
+			out.WriteByte(table[(val>>uint(valb))&0x3F])
+			valb -= 6
+		}
+	}
+	if valb > -6 {
+		out.WriteByte(table[((val << uint(8+valb)) & 0x3F)])
+	}
+	for out.Len()%4 != 0 {
+		out.WriteByte('=')
+	}
+	return out.String()
