+	errs := make(chan error, 1)
+	streamCtx, cancel := context.WithCancel(ctx)
+
+	go func() {
+		defer cancel()
+		defer resp.Body.Close()
+
+		events <- StreamEvent{Type: StreamStart}
+		sseOut := make(chan sseEvent, 64)
+		sseErr := make(chan error, 1)
+		go decodeSSE(streamCtx, resp.Body, sseOut, sseErr)
+
+		var textID = "text"
+		var started bool
+		var textBuf strings.Builder
+		var lastUsage *Usage
+		var finishReason FinishReason
+
+		for {
+			select {
+			case <-streamCtx.Done():
+				errs <- streamCtx.Err()
+				close(events)
+				return
+			case ev, ok := <-sseOut:
+				if !ok {
+					err := <-sseErr
+					if err == nil {
+						err = io.EOF
+					}
+					errs <- err
+					close(events)
+					return
+				}
+				if strings.TrimSpace(ev.Data) == "" {
+					continue
+				}
+				var payload map[string]any
+				if err := json.Unmarshal([]byte(ev.Data), &payload); err != nil {
+					events <- StreamEvent{Type: ProviderEvent, Raw: ev.Data}
+					continue
+				}
+				deltas, calls, fr, usage := geminiExtractDeltas(payload)
+				if usage != nil {
+					lastUsage = usage
+				}
+				if fr != nil {
+					finishReason = *fr
+				}
+				for _, d := range deltas {
+					if !started {
+						started = true
+						id := textID
+						events <- StreamEvent{Type: TextStart, TextID: &id}
+					}
+					textBuf.WriteString(d)
+					dd := d
+					id := textID
+					events <- StreamEvent{Type: TextDelta, TextID: &id, Delta: &dd}
+				}
+				for _, tc := range calls {
+					events <- StreamEvent{Type: ToolCallStart, ToolCall: &tc}
+					events <- StreamEvent{Type: ToolCallEnd, ToolCall: &tc}
+				}
+				// best-effort finish: Gemini doesn't always send an explicit stop signal; treat presence of finishReason as end.
+				if finishReason.Reason != "" && (finishReason.Raw != nil) {
+					if started {
+						id := textID
+						events <- StreamEvent{Type: TextEnd, TextID: &id}
+					}
+					txt := textBuf.String()
+					resp := Response{
+						ID:           "",
+						Model:        req.Model,
+						Provider:     "gemini",
+						Message:      Message{Role: RoleAssistant, Content: []ContentPart{TextPart(txt)}},
+						FinishReason: finishReason,
+						Usage:        Usage{},
+						Raw:          payload,
+					}
+					if lastUsage != nil {
+						resp.Usage = *lastUsage
+					}
+					fr2 := resp.FinishReason
+					u2 := resp.Usage
+					events <- StreamEvent{Type: StreamFinish, FinishReason: &fr2, Usage: &u2, Response: &resp}
+				}
+			}
+		}
+	}()
+
+	return newChanEventStream(ctx, events, errs, cancel), nil
+}
+
+func (a *GeminiAdapter) translateRequest(req Request, stream bool) (map[string]any, map[string]string, string, error) {
+	if strings.TrimSpace(req.Model) == "" {
+		return nil, nil, "", &SDKError{Type: "InvalidRequestError", Message: "model is required"}
+	}
+
+	systemText := extractInstructions(req.Messages)
+	idToName := map[string]string{}
+	for _, m := range req.Messages {
+		for _, p := range m.Content {
+			if p.Kind == ContentToolCall && p.ToolCall != nil {
+				idToName[p.ToolCall.ID] = p.ToolCall.Name
+			}
+		}
+	}
+
+	contents := []any{}
+	for _, m := range req.Messages {
+		if m.Role == RoleSystem || m.Role == RoleDeveloper {
+			continue
+		}
+		role := "user"
+		if m.Role == RoleAssistant {
+			role = "model"
+		}
+		parts := []any{}
+		switch m.Role {
+		case RoleTool:
+			for _, p := range m.Content {
+				if p.Kind == ContentToolResult && p.ToolResult != nil {
+					name := idToName[p.ToolResult.ToolCallID]
+					if name == "" {
+						name = "tool"
+					}
+					respVal := p.ToolResult.Content
+					if s, ok := respVal.(string); ok {
+						respVal = map[string]any{"result": s}
+					}
+					parts = append(parts, map[string]any{"functionResponse": map[string]any{"name": name, "response": respVal}})
+				}
+			}
+			role = "user"
+		default:
+			for _, p := range m.Content {
+				switch p.Kind {
+				case ContentText:
+					if p.Text != nil {
+						parts = append(parts, map[string]any{"text": *p.Text})
+					}
+				case ContentImage:
+					if p.Image == nil {
+						continue
+					}
+					img, err := p.Image.ResolveDataFromURLIfLocal()
+					if err != nil {
+						return nil, nil, "", err
+					}
+					mt := "image/png"
+					if img.MediaType != nil && *img.MediaType != "" {
+						mt = *img.MediaType
+					}
+					if img.URL != nil {
+						parts = append(parts, map[string]any{"fileData": map[string]any{"mimeType": mt, "fileUri": *img.URL}})
+					} else if len(img.Data) > 0 {
+						parts = append(parts, map[string]any{"inlineData": map[string]any{"mimeType": mt, "data": base64Std(img.Data)}})
+					}
+				case ContentToolCall:
+					if p.ToolCall == nil {
+						continue
+					}
+					args := p.ToolCall.Arguments
+					if s, ok := args.(string); ok {
+						var m2 map[string]any
+						_ = json.Unmarshal([]byte(s), &m2)
+						args = m2
+					}
+					if m2, ok := args.(map[string]any); ok {
+						parts = append(parts, map[string]any{"functionCall": map[string]any{"name": p.ToolCall.Name, "args": m2}})
+					} else {
+						parts = append(parts, map[string]any{"functionCall": map[string]any{"name": p.ToolCall.Name, "args": map[string]any{}}})
+					}
+				}
+			}
+		}
+		if len(parts) > 0 {
+			contents = append(contents, map[string]any{"role": role, "parts": parts})
+		}
+	}
+
+	body := map[string]any{
+		"contents": contents,
+	}
+	if systemText != "" {
+		body["systemInstruction"] = map[string]any{"parts": []any{map[string]any{"text": systemText}}}
+	}
+
+	if len(req.Tools) > 0 {
+		decls := []any{}
+		for _, t := range req.Tools {
+			var params any
+			_ = json.Unmarshal(t.Parameters, &params)
+			decls = append(decls, map[string]any{"name": t.Name, "description": t.Description, "parameters": params})
+		}
+		body["tools"] = []any{map[string]any{"functionDeclarations": decls}}
+		if req.ToolChoice != nil {
+			body["toolConfig"] = map[string]any{"functionCallingConfig": translateGeminiToolChoice(*req.ToolChoice)}
+		}
+	}
+
+	genCfg := map[string]any{}
+	if req.Temperature != nil {
+		genCfg["temperature"] = *req.Temperature
+	}
+	if req.TopP != nil {
+		genCfg["topP"] = *req.TopP
+	}
+	if req.MaxTokens != nil {
+		genCfg["maxOutputTokens"] = *req.MaxTokens
+	}
+	if len(req.StopSequences) > 0 {
+		genCfg["stopSequences"] = req.StopSequences
+	}
+	if req.ResponseFormat != nil {
+		switch req.ResponseFormat.Type {
+		case "json", "json_schema":
+			genCfg["responseMimeType"] = "application/json"
+			if req.ResponseFormat.Type == "json_schema" {
+				var schema any
+				_ = json.Unmarshal(req.ResponseFormat.JSONSchema, &schema)
+				genCfg["responseSchema"] = schema
+			}
+		}
+	}
+	if len(genCfg) > 0 {
+		body["generationConfig"] = genCfg
+	}
+
+	if req.ProviderOptions != nil {
+		if v, ok := req.ProviderOptions["gemini"]; ok {
+			if m, ok := v.(map[string]any); ok {
+				for k, vv := range m {
+					body[k] = vv
+				}
+			}
+		}
+	}
+
+	path := fmt.Sprintf("/v1beta/models/%s:generateContent", url.PathEscape(req.Model))
+	if stream {
+		// Use alt=sse for streaming chunks.
+		path = fmt.Sprintf("/v1beta/models/%s:generateContent", url.PathEscape(req.Model))
+	}
+	u, err := url.Parse(joinURL(a.cfg.BaseURL, path))
+	if err != nil {
+		return nil, nil, "", err
+	}
+	q := u.Query()
+	q.Set("key", a.cfg.APIKey)
+	if stream {
+		q.Set("alt", "sse")
+	}
+	u.RawQuery = q.Encode()
+
+	return body, map[string]string{}, u.String(), nil
+}
+
+func translateGeminiToolChoice(tc ToolChoice) any {
+	switch tc.Mode {
+	case "auto":
+		return map[string]any{"mode": "AUTO"}
+	case "none":
+		return map[string]any{"mode": "NONE"}
+	case "required":
+		return map[string]any{"mode": "ANY"}
+	case "named":
+		if tc.ToolName == nil || *tc.ToolName == "" {
+			return map[string]any{"mode": "AUTO"}
+		}
+		return map[string]any{"mode": "ANY", "allowedFunctionNames": []any{*tc.ToolName}}
+	default:
+		return map[string]any{"mode": "AUTO"}
+	}
+}
+
+func (a *GeminiAdapter) translateHTTPError(resp *http.Response, body []byte) error {
+	var parsed any
+	_ = json.Unmarshal(body, &parsed)
+	msg := strings.TrimSpace(string(body))
+	var code *string
+	if m, ok := parsed.(map[string]any); ok {
+		if errObj, ok := m["error"].(map[string]any); ok {
+			if s, ok := errObj["message"].(string); ok && s != "" {
+				msg = s
+			}
+			if s, ok := errObj["status"].(string); ok && s != "" {
+				code = &s
+			}
+		}
+	}
+	retryAfter := ParseRetryAfter(resp.Header.Get("retry-after"))
+	return NewProviderError("gemini", resp.StatusCode, msg, code, parsed, retryAfter)
+}
+
+func (a *GeminiAdapter) translateResponse(raw any) (Response, error) {
+	m, ok := raw.(map[string]any)
+	if !ok {
+		return Response{}, fmt.Errorf("unexpected response shape")
+	}
+	cands, _ := m["candidates"].([]any)
+	var contentParts []ContentPart
+	finish := FinishReason{Reason: "stop"}
+	if len(cands) > 0 {
+		c0, _ := cands[0].(map[string]any)
+		if fr, ok := c0["finishReason"].(string); ok && fr != "" {
+			rawFR := fr
+			finish.Raw = &rawFR
+			switch fr {
+			case "STOP":
+				finish.Reason = "stop"
+			case "MAX_TOKENS":
+				finish.Reason = "length"
+			case "SAFETY", "RECITATION":
+				finish.Reason = "content_filter"
+			default:
+				finish.Reason = "other"
+			}
+		}
+		if content, ok := c0["content"].(map[string]any); ok {
+			if parts, ok := content["parts"].([]any); ok {
+				callIdx := 0
+				for _, p := range parts {
+					pm, _ := p.(map[string]any)
+					if pm == nil {
+						continue
+					}
+					if t, ok := pm["text"].(string); ok {
+						contentParts = append(contentParts, TextPart(t))
+					}
+					if fc, ok := pm["functionCall"].(map[string]any); ok {
+						callIdx++
+						name, _ := fc["name"].(string)
+						args, _ := fc["args"].(map[string]any)
+						id := "call_" + strconv.Itoa(callIdx)
+						contentParts = append(contentParts, ContentPart{
+							Kind: ContentToolCall,
+							ToolCall: &ToolCallData{ID: id, Name: name, Arguments: args, Type: "function"},
+						})
+						finish.Reason = "tool_calls"
+					}
+				}
+			}
+		}
+	}
+
+	usage := Usage{}
+	if um, ok := m["usageMetadata"].(map[string]any); ok {
+		usage.Raw = um
+		if v, ok := um["promptTokenCount"].(float64); ok {
+			usage.InputTokens = int(v)
+		}
+		if v, ok := um["candidatesTokenCount"].(float64); ok {
+			usage.OutputTokens = int(v)
+		}
+		if v, ok := um["thoughtsTokenCount"].(float64); ok {
+			ri := int(v)
+			usage.ReasoningTokens = &ri
+		}
+		if v, ok := um["cachedContentTokenCount"].(float64); ok {
+			ci := int(v)
+			usage.CacheReadTokens = &ci
+		}
+	}
+
+	return Response{
+		ID:           "",
+		Model:        reqModelFromRaw(m),
+		Provider:     "gemini",
+		Message:      Message{Role: RoleAssistant, Content: contentParts},
+		FinishReason: finish,
+		Usage:        usage,
+		Raw:          raw,
+	}, nil
+}
+
+func reqModelFromRaw(m map[string]any) string {
+	if s, ok := m["model"].(string); ok && s != "" {
+		return s
+	}
+	return ""
+}
+
+func geminiExtractDeltas(payload map[string]any) ([]string, []ToolCall, *FinishReason, *Usage) {
+	var deltas []string
+	var calls []ToolCall
+	var finish *FinishReason
+	var usage *Usage
+
+	if um, ok := payload["usageMetadata"].(map[string]any); ok {
+		u := Usage{Raw: um}
+		if v, ok := um["promptTokenCount"].(float64); ok {
+			u.InputTokens = int(v)
+		}
+		if v, ok := um["candidatesTokenCount"].(float64); ok {
+			u.OutputTokens = int(v)
+		}
+		if v, ok := um["thoughtsTokenCount"].(float64); ok {
+			ri := int(v)
+			u.ReasoningTokens = &ri
+		}
+		if v, ok := um["cachedContentTokenCount"].(float64); ok {
+			ci := int(v)
+			u.CacheReadTokens = &ci
+		}
+		usage = &u
+	}
+
+	cands, _ := payload["candidates"].([]any)
+	if len(cands) > 0 {
+		c0, _ := cands[0].(map[string]any)
+		if fr, ok := c0["finishReason"].(string); ok && fr != "" {
+			rawFR := fr
+			f := FinishReason{Raw: &rawFR}
+			switch fr {
+			case "STOP":
+				f.Reason = "stop"
+			case "MAX_TOKENS":
+				f.Reason = "length"
+			case "SAFETY", "RECITATION":
+				f.Reason = "content_filter"
+			default:
+				f.Reason = "other"
+			}
+			finish = &f
+		}
+		if content, ok := c0["content"].(map[string]any); ok {
+			if parts, ok := content["parts"].([]any); ok {
+				callIdx := 0
+				for _, p := range parts {
+					pm, _ := p.(map[string]any)
+					if pm == nil {
+						continue
+					}
+					if t, ok := pm["text"].(string); ok && t != "" {
