+package llmsdk
+
+import (
+	"context"
+	"encoding/json"
+	"fmt"
+	"math"
+	"math/rand"
+	"time"
+)
+
+type StepResult struct {
+	Text         string       `json:"text"`
+	Reasoning    *string      `json:"reasoning,omitempty"`
+	ToolCalls    []ToolCall   `json:"tool_calls,omitempty"`
+	ToolResults  []ToolResult `json:"tool_results,omitempty"`
+	FinishReason FinishReason `json:"finish_reason"`
+	Usage        Usage        `json:"usage"`
+	Response     Response     `json:"response"`
+	Warnings     []Warning    `json:"warnings,omitempty"`
+}
+
+type GenerateResult struct {
+	Text         string       `json:"text"`
+	Reasoning    *string      `json:"reasoning,omitempty"`
+	ToolCalls    []ToolCall   `json:"tool_calls,omitempty"`
+	ToolResults  []ToolResult `json:"tool_results,omitempty"`
+	FinishReason FinishReason `json:"finish_reason"`
+	Usage        Usage        `json:"usage"`
+	TotalUsage   Usage        `json:"total_usage"`
+	Steps        []StepResult `json:"steps"`
+	Response     Response     `json:"response"`
+	Output       any          `json:"output,omitempty"`
+}
+
+type GenerateParams struct {
+	Request       Request
+	MaxToolRounds int
+	MaxRetries    int
+	RetryPolicy   *RetryPolicy
+	Client        *Client
+}
+
+type RetryPolicy struct {
+	MaxRetries        int
+	BaseDelaySeconds  float64
+	MaxDelaySeconds   float64
+	BackoffMultiplier float64
+	Jitter            bool
+}
+
+func defaultRetryPolicy(maxRetries int) RetryPolicy {
+	return RetryPolicy{
+		MaxRetries:        maxRetries,
+		BaseDelaySeconds:  1.0,
+		MaxDelaySeconds:   60.0,
+		BackoffMultiplier: 2.0,
+		Jitter:            true,
+	}
+}
+
+func Generate(ctx context.Context, params GenerateParams) (GenerateResult, error) {
+	c := params.Client
+	if c == nil {
+		var err error
+		c, err = DefaultClient()
+		if err != nil {
+			return GenerateResult{}, err
+		}
+	}
+	req := params.Request
+	maxToolRounds := params.MaxToolRounds
+	if maxToolRounds < 0 {
+		maxToolRounds = 0
+	}
+	maxRetries := params.MaxRetries
+	if maxRetries < 0 {
+		maxRetries = 0
+	}
+	pol := params.RetryPolicy
+	if pol == nil {
+		p := defaultRetryPolicy(maxRetries)
+		pol = &p
+	}
+
+	conversation := append([]Message{}, req.Messages...)
+	totalUsage := Usage{}
+	var steps []StepResult
+	var lastResp Response
+	var lastToolResults []ToolResult
+
+	round := 0
+	for {
+		req.Messages = conversation
+		resp, err := completeWithRetry(ctx, c, req, *pol)
+		if err != nil {
+			return GenerateResult{}, err
+		}
+		lastResp = resp
+		totalUsage = totalUsage.Add(resp.Usage)
+
+		tr := []ToolResult{}
+		tcs := resp.ToolCalls()
+		if len(tcs) > 0 {
+			// If maxToolRounds == 0, do not execute tools.
+			if maxToolRounds == 0 {
+				steps = append(steps, StepResult{
+					Text:         resp.Text(),
+					Reasoning:    resp.Reasoning(),
+					ToolCalls:    tcs,
+					ToolResults:  nil,
+					FinishReason: resp.FinishReason,
+					Usage:        resp.Usage,
+					Response:     resp,
+					Warnings:     resp.Warnings,
+				})
+				break
+			}
+			tr = executeToolsConcurrently(ctx, req.Tools, tcs, conversation)
+			lastToolResults = tr
+		}
+
+		steps = append(steps, StepResult{
+			Text:         resp.Text(),
+			Reasoning:    resp.Reasoning(),
+			ToolCalls:    tcs,
+			ToolResults:  tr,
+			FinishReason: resp.FinishReason,
+			Usage:        resp.Usage,
+			Response:     resp,
+			Warnings:     resp.Warnings,
+		})
+
+		// stop conditions
+		if len(tcs) == 0 || resp.FinishReason.Reason != "tool_calls" {
+			break
+		}
+		if maxToolRounds > 0 && round >= maxToolRounds {
+			break
+		}
+		round++
+
+		// continue conversation
+		conversation = append(conversation, resp.Message)
+		for _, r := range tr {
+			conversation = append(conversation, ToolResultMessage(r.ToolCallID, r.Content, r.IsError))
+		}
+	}
+
+	finalToolCalls := lastResp.ToolCalls()
+	return GenerateResult{
+		Text:         lastResp.Text(),
+		Reasoning:    lastResp.Reasoning(),
+		ToolCalls:    finalToolCalls,
+		ToolResults:  lastToolResults,
+		FinishReason: lastResp.FinishReason,
+		Usage:        lastResp.Usage,
+		TotalUsage:   totalUsage,
+		Steps:        steps,
+		Response:     lastResp,
+	}, nil
+}
+
+func completeWithRetry(ctx context.Context, c *Client, req Request, pol RetryPolicy) (Response, error) {
+	attempts := 0
+	for {
+		resp, err := c.Complete(ctx, req)
+		if err == nil {
+			return resp, nil
+		}
+		pe := (*ProviderError)(nil)
+		switch e := err.(type) {
+		case *ProviderError:
+			pe = e
+		}
+		if pe == nil || !pe.Retryable || attempts >= pol.MaxRetries {
+			return Response{}, err
+		}
+		delay := backoffDelay(pol, attempts, pe.RetryAfter)
+		timer := time.NewTimer(delay)
+		select {
+		case <-ctx.Done():
+			timer.Stop()
+			return Response{}, &SDKError{Type: "AbortError", Message: ctx.Err().Error()}
+		case <-timer.C:
+		}
+		attempts++
+	}
+}
+
+func backoffDelay(pol RetryPolicy, attempt int, retryAfter *float64) time.Duration {
+	if retryAfter != nil {
+		ra := *retryAfter
+		if ra > pol.MaxDelaySeconds {
+			return time.Duration(pol.MaxDelaySeconds * float64(time.Second))
+		}
+		return time.Duration(ra * float64(time.Second))
+	}
+	d := pol.BaseDelaySeconds * math.Pow(pol.BackoffMultiplier, float64(attempt))
+	if d > pol.MaxDelaySeconds {
+		d = pol.MaxDelaySeconds
+	}
+	if pol.Jitter {
+		d = d * (0.5 + rand.Float64())
+	}
+	return time.Duration(d * float64(time.Second))
+}
+
+func executeToolsConcurrently(ctx context.Context, tools []Tool, calls []ToolCall, messages []Message) []ToolResult {
+	toolByName := map[string]Tool{}
+	for _, t := range tools {
+		toolByName[t.Name] = t
+	}
+	type out struct {
+		idx int
+		res ToolResult
+	}
+	ch := make(chan out, len(calls))
+	for i, call := range calls {
+		go func(i int, call ToolCall) {
+			t, ok := toolByName[call.Name]
+			if !ok || t.Execute == nil {
+				ch <- out{idx: i, res: ToolResult{ToolCallID: call.ID, Content: "Unknown tool: " + call.Name, IsError: true}}
+				return
+			}
+			res, err := t.Execute(ToolContext{ToolCallID: call.ID, Arguments: call.Arguments, Messages: messages})
+			if err != nil {
