+		}
+	}
+	req := params.Request
+	maxToolRounds := params.MaxToolRounds
+	if maxToolRounds < 0 {
+		maxToolRounds = 0
+	}
+	maxRetries := params.MaxRetries
+	if maxRetries < 0 {
+		maxRetries = 0
+	}
