+			Text:         resp.Text(),
+			Reasoning:    resp.Reasoning(),
+			ToolCalls:    tcs,
+			ToolResults:  tr,
+			FinishReason: resp.FinishReason,
+			Usage:        resp.Usage,
+			Response:     resp,
+			Warnings:     resp.Warnings,
