+package llmsdk
+
+import (
+	"encoding/json"
+	"fmt"
+)
+
+// ValidateAgainstSchema implements a minimal JSON Schema validator sufficient for the spec's
+// structured output conformance: type, properties, required, items, enum.
+func ValidateAgainstSchema(schema json.RawMessage, value any) error {
+	if len(schema) == 0 {
+		return nil
+	}
+	var s any
+	if err := json.Unmarshal(schema, &s); err != nil {
+		return fmt.Errorf("invalid schema JSON: %w", err)
+	}
+	return validateSchemaNode(s, value, "$")
+}
+
+func validateSchemaNode(schema any, value any, path string) error {
+	m, ok := schema.(map[string]any)
+	if !ok {
+		return nil
+	}
+	if enumVals, ok := m["enum"].([]any); ok {
+		for _, ev := range enumVals {
+			if deepEqualJSON(ev, value) {
+				return nil
+			}
+		}
+		return fmt.Errorf("%s: value not in enum", path)
+	}
+	typ, _ := m["type"].(string)
+	switch typ {
+	case "object":
+		obj, ok := value.(map[string]any)
+		if !ok {
+			return fmt.Errorf("%s: expected object", path)
+		}
+		if req, ok := m["required"].([]any); ok {
+			for _, r := range req {
+				key, _ := r.(string)
+				if key == "" {
+					continue
+				}
+				if _, exists := obj[key]; !exists {
+					return fmt.Errorf("%s: missing required property %q", path, key)
+				}
+			}
+		}
+		props, _ := m["properties"].(map[string]any)
+		for k, propSchema := range props {
+			if v, exists := obj[k]; exists {
+				if err := validateSchemaNode(propSchema, v, path+"."+k); err != nil {
+					return err
+				}
+			}
+		}
+		return nil
+	case "array":
+		arr, ok := value.([]any)
+		if !ok {
+			return fmt.Errorf("%s: expected array", path)
+		}
+		if items, ok := m["items"]; ok {
+			for i, v := range arr {
+				if err := validateSchemaNode(items, v, fmt.Sprintf("%s[%d]", path, i)); err != nil {
+					return err
+				}
+			}
+		}
+		return nil
+	case "string":
+		if _, ok := value.(string); !ok {
+			return fmt.Errorf("%s: expected string", path)
+		}
+		return nil
+	case "integer":
+		switch value.(type) {
+		case float64: // JSON numbers
+			f := value.(float64)
+			if f != float64(int64(f)) {
+				return fmt.Errorf("%s: expected integer", path)
+			}
+			return nil
+		case int, int32, int64, uint64:
+			return nil
+		default:
+			return fmt.Errorf("%s: expected integer", path)
+		}
+	case "number":
+		if _, ok := value.(float64); !ok {
+			return fmt.Errorf("%s: expected number", path)
+		}
+		return nil
+	case "boolean":
+		if _, ok := value.(bool); !ok {
+			return fmt.Errorf("%s: expected boolean", path)
+		}
+		return nil
+	default:
+		// unknown/unsupported schema keyword: be permissive
+		return nil
+	}
+}
+
+func deepEqualJSON(a, b any) bool {
+	ab, _ := json.Marshal(a)
+	bb, _ := json.Marshal(b)
+	return string(ab) == string(bb)
+}
+
