+
+func (d *ToolDispatcher) ExecuteAll(ctx context.Context, calls []llmsdk.ToolCall, supportsParallel bool) []llmsdk.ToolResult {
+	results := make([]llmsdk.ToolResult, len(calls))
+	if supportsParallel && len(calls) > 1 {
+		type out struct {
+			idx int
+			res llmsdk.ToolResult
+		}
+		ch := make(chan out, len(calls))
+		for i, c := range calls {
+			go func(i int, c llmsdk.ToolCall) {
+				ch <- out{idx: i, res: d.executeOne(ctx, c)}
+			}(i, c)
+		}
+		for i := 0; i < len(calls); i++ {
+			o := <-ch
+			results[o.idx] = o.res
+		}
