+		if d.Emit != nil {
+			d.Emit(SessionEvent{Kind: EventToolCallEnd, Timestamp: now(), SessionID: d.SessionID, Data: map[string]any{"call_id": call.ID, "error": msg, "output": msg}})
+		}
