+package agent
+
+import (
+	"bytes"
+	"context"
+	"errors"
+	"fmt"
+	"io"
+	"io/fs"
+	"os"
+	"os/exec"
+	"path/filepath"
+	"regexp"
+	"runtime"
+	"strings"
+	"syscall"
+	"time"
+)
+
+type ExecResult struct {
+	Stdout     string `json:"stdout"`
+	Stderr     string `json:"stderr"`
+	ExitCode   int    `json:"exit_code"`
+	TimedOut   bool   `json:"timed_out"`
+	DurationMS int    `json:"duration_ms"`
+}
+
+type DirEntry struct {
+	Name  string `json:"name"`
+	IsDir bool   `json:"is_dir"`
+	Size  *int64 `json:"size,omitempty"`
+}
+
+type ExecutionEnvironment interface {
+	ReadFile(path string, offset *int, limit *int) (string, error)
+	WriteFile(path string, content string) error
+	FileExists(path string) bool
+	ListDirectory(path string, depth int) ([]DirEntry, error)
+
+	ExecCommand(command string, timeoutMS int, workingDir *string, envVars map[string]string) (ExecResult, error)
+
+	Grep(pattern string, path string, globFilter *string, caseInsensitive bool, maxResults int) (string, error)
+	Glob(pattern string, path string) ([]string, error)
+
+	WorkingDirectory() string
+	Platform() string
+	OSVersion() string
+}
+
+type LocalExecutionEnvironment struct {
+	root string
+}
+
+func NewLocalExecutionEnvironment(root string) *LocalExecutionEnvironment {
+	if root == "" {
+		root, _ = os.Getwd()
+	}
+	return &LocalExecutionEnvironment{root: root}
+}
+
+func (e *LocalExecutionEnvironment) WorkingDirectory() string { return e.root }
+
+func (e *LocalExecutionEnvironment) Platform() string { return runtime.GOOS }
+
+func (e *LocalExecutionEnvironment) OSVersion() string { return runtime.Version() }
+
+func (e *LocalExecutionEnvironment) abs(p string) string {
+	if filepath.IsAbs(p) {
+		return p
+	}
+	return filepath.Join(e.root, p)
+}
+
+func (e *LocalExecutionEnvironment) ReadFile(path string, offset *int, limit *int) (string, error) {
+	b, err := os.ReadFile(e.abs(path))
+	if err != nil {
+		return "", err
+	}
+	s := string(b)
+	start := 0
+	if offset != nil && *offset > 0 {
+		start = *offset
+		if start > len(s) {
+			start = len(s)
+		}
+	}
+	end := len(s)
+	if limit != nil && *limit >= 0 {
+		if start+*limit < end {
+			end = start + *limit
+		}
+	}
+	return s[start:end], nil
+}
+
+func (e *LocalExecutionEnvironment) WriteFile(path string, content string) error {
+	ap := e.abs(path)
+	if err := os.MkdirAll(filepath.Dir(ap), 0o755); err != nil {
+		return err
+	}
+	return os.WriteFile(ap, []byte(content), 0o644)
+}
+
+func (e *LocalExecutionEnvironment) FileExists(path string) bool {
+	_, err := os.Stat(e.abs(path))
+	return err == nil
+}
+
+func (e *LocalExecutionEnvironment) ListDirectory(path string, depth int) ([]DirEntry, error) {
+	base := e.abs(path)
+	if depth < 0 {
+		depth = 0
+	}
+	var out []DirEntry
+	err := filepath.WalkDir(base, func(p string, d fs.DirEntry, err error) error {
+		if err != nil {
+			return err
+		}
+		if p == base {
+			return nil
+		}
+		rel, _ := filepath.Rel(base, p)
+		if depth > 0 {
+			if strings.Count(filepath.ToSlash(rel), "/") >= depth {
+				if d.IsDir() {
+					return filepath.SkipDir
+				}
+				return nil
+			}
+		}
+		var size *int64
+		if info, err := d.Info(); err == nil && !d.IsDir() {
+			sz := info.Size()
+			size = &sz
+		}
+		out = append(out, DirEntry{Name: filepath.ToSlash(rel), IsDir: d.IsDir(), Size: size})
+		return nil
+	})
+	return out, err
+}
+
+func (e *LocalExecutionEnvironment) ExecCommand(command string, timeoutMS int, workingDir *string, envVars map[string]string) (ExecResult, error) {
+	if timeoutMS <= 0 {
+		timeoutMS = 10000
+	}
+	wd := e.root
+	if workingDir != nil && *workingDir != "" {
+		wd = e.abs(*workingDir)
+	}
+	ctx, cancel := context.WithTimeout(context.Background(), time.Duration(timeoutMS)*time.Millisecond)
+	defer cancel()
+
+	cmd := exec.CommandContext(ctx, "/bin/bash", "-lc", command)
+	cmd.Dir = wd
+	cmd.SysProcAttr = &syscall.SysProcAttr{Setpgid: true}
+
+	cmd.Env = filteredEnv(os.Environ(), envVars)
+
+	var stdout, stderr bytes.Buffer
+	cmd.Stdout = &stdout
+	cmd.Stderr = &stderr
+
+	start := time.Now()
+	err := cmd.Start()
+	if err != nil {
+		return ExecResult{}, err
+	}
+
+	waitCh := make(chan error, 1)
+	go func() { waitCh <- cmd.Wait() }()
+
+	timedOut := false
+	select {
+	case err = <-waitCh:
+	case <-ctx.Done():
+		timedOut = true
+		_ = killProcessGroup(cmd.Process.Pid, syscall.SIGTERM)
+		select {
