+func (p *BaseProfile) BuildSystemPrompt(env ExecutionEnvironment, projectDocs map[string]string) string {
+	now := time.Now().Format(time.RFC3339)
+	wd := ""
+	plat := runtime.GOOS
+	if env != nil {
+		wd = env.WorkingDirectory()
+		plat = env.Platform()
+	}
+	docSummary := ""
+	for k := range projectDocs {
+		docSummary += fmt.Sprintf("- %s\n", k)
