+	}
+	return fmt.Sprintf("You are a coding agent.\n\nEnvironment:\n- platform: %s\n- working_directory: %s\n- time: %s\n\nProject docs:\n%s\n\nUse tools when helpful and be careful with edits.\n", plat, wd, now, docSummary)
