+
+func DiscoverProjectDocs(env ExecutionEnvironment, root string, provider string) map[string]string {
+	docs := map[string]string{}
+	_ = root
+	// Minimal discovery: AGENTS.md anywhere up to a small depth, and provider-specific files.
+	candidates := []string{"AGENTS.md"}
+	switch provider {
+	case "openai":
+		candidates = append(candidates, ".codex/instructions.md")
