+package agent
+
+import (
+	"context"
+	"crypto/sha256"
+	"encoding/hex"
+	"encoding/json"
+	"fmt"
+	"sync"
+	"time"
+
+	"attractorbench/pkg/llmsdk"
+)
+
+type Session struct {
+	ID              string         `json:"id"`
+	ProviderProfile ProviderProfile `json:"-"`
+	ExecutionEnv    ExecutionEnvironment `json:"-"`
+	Config          SessionConfig   `json:"config"`
+	State           SessionState    `json:"state"`
+	History         []Turn          `json:"history"`
+
+	LLMClient *llmsdk.Client `json:"-"`
+
+	events chan SessionEvent
+
+	mu            sync.Mutex
+	steeringQueue []string
+	followupQueue []string
+}
+
+type SessionResult struct {
+	ID      string       `json:"id"`
+	State   SessionState `json:"state"`
+	History []Turn       `json:"history"`
+}
+
+func NewSession(profile ProviderProfile, env ExecutionEnvironment, client *llmsdk.Client, cfg *SessionConfig) (*Session, error) {
+	if cfg == nil {
+		def := DefaultSessionConfig()
+		cfg = &def
+	}
+	if client == nil {
+		c, err := llmsdk.DefaultClient()
+		if err != nil {
+			return nil, err
+		}
+		client = c
+	}
+	s := &Session{
+		ID:              newSessionID(),
+		ProviderProfile: profile,
+		ExecutionEnv:    env,
+		Config:          *cfg,
+		State:           StateIdle,
+		LLMClient:       client,
+		events:          make(chan SessionEvent, 512),
+	}
+	s.emit(EventSessionStart, map[string]any{"provider": profile.ID(), "model": profile.Model()})
+	return s, nil
+}
+
+func (s *Session) Events() <-chan SessionEvent { return s.events }
+
+func (s *Session) Close() {
+	s.mu.Lock()
+	defer s.mu.Unlock()
+	if s.State == StateClosed {
+		return
+	}
+	s.State = StateClosed
+	s.emit(EventSessionEnd, map[string]any{"state": s.State})
+	close(s.events)
+}
+
+func (s *Session) Steer(msg string) {
+	s.mu.Lock()
+	defer s.mu.Unlock()
+	s.steeringQueue = append(s.steeringQueue, msg)
+}
+
+func (s *Session) FollowUp(msg string) {
+	s.mu.Lock()
+	defer s.mu.Unlock()
+	s.followupQueue = append(s.followupQueue, msg)
+}
+
+func (s *Session) drainSteering() {
+	s.mu.Lock()
+	msgs := append([]string{}, s.steeringQueue...)
+	s.steeringQueue = nil
+	s.mu.Unlock()
+	for _, msg := range msgs {
+		s.History = append(s.History, Turn{Kind: TurnSteering, Steering: &SteeringTurn{Content: msg, Timestamp: now()}})
+		s.emit(EventSteeringInjected, map[string]any{"content": msg})
+	}
+}
+
+func (s *Session) ProcessInput(ctx context.Context, userInput string) (SessionResult, error) {
+	if s.State == StateClosed {
+		return SessionResult{ID: s.ID, State: s.State, History: s.History}, &llmsdk.SDKError{Type: "ConfigurationError", Message: "session is closed"}
+	}
+	s.State = StateProcessing
+	s.History = append(s.History, Turn{Kind: TurnUser, User: &UserTurn{Content: userInput, Timestamp: now()}})
+	s.emit(EventUserInput, map[string]any{"content": userInput})
+
+	s.drainSteering()
+
+	roundCount := 0
+	for {
+		if s.Config.MaxToolRoundsPerInput > 0 && roundCount >= s.Config.MaxToolRoundsPerInput {
+			s.emit(EventTurnLimit, map[string]any{"round": roundCount})
+			break
+		}
+		if s.Config.MaxTurns > 0 && countTurns(s.History) >= s.Config.MaxTurns {
+			s.emit(EventTurnLimit, map[string]any{"total_turns": countTurns(s.History)})
+			break
+		}
+		if err := ctx.Err(); err != nil {
+			s.State = StateClosed
+			s.emit(EventError, map[string]any{"error": err.Error()})
+			break
+		}
+
+		systemPrompt := s.ProviderProfile.BuildSystemPrompt(s.ExecutionEnv, DiscoverProjectDocs(s.ExecutionEnv, s.ExecutionEnv.WorkingDirectory(), s.ProviderProfile.ID()))
+		messages := historyToMessages(s.History)
+		req := llmsdk.Request{
+			Model:           s.ProviderProfile.Model(),
+			Messages:        append([]llmsdk.Message{llmsdk.SystemMessage(systemPrompt)}, messages...),
+			Tools:           s.ProviderProfile.Tools(),
+			ToolChoice:      &llmsdk.ToolChoice{Mode: "auto"},
+			ReasoningEffort: s.Config.ReasoningEffort,
+			Provider:        strPtr(s.ProviderProfile.ID()),
+			ProviderOptions: s.ProviderProfile.ProviderOptions(),
+		}
+
+		resp, err := s.LLMClient.Complete(ctx, req)
+		if err != nil {
+			s.State = StateClosed
+			s.emit(EventError, map[string]any{"error": err.Error()})
+			break
+		}
+
+		tcs := resp.ToolCalls()
+		assistantTurn := AssistantTurn{
+			Content:    resp.Text(),
+			ToolCalls:  tcs,
+			Reasoning:  resp.Reasoning(),
+			Usage:      resp.Usage,
+			ResponseID: &resp.ID,
+			Timestamp:  now(),
+		}
+		s.History = append(s.History, Turn{Kind: TurnAssistant, Assistant: &assistantTurn})
+		s.emit(EventAssistantTextEnd, map[string]any{"text": resp.Text(), "reasoning": resp.Reasoning()})
+
+		if len(tcs) == 0 {
+			break
+		}
+
+		roundCount++
+
+		dispatcher := &ToolDispatcher{
+			Registry:   s.ProviderProfile.ToolRegistry(),
+			Config:     s.Config,
+			Env:        s.ExecutionEnv,
+			Emit:       func(ev SessionEvent) { s.emit(ev.Kind, ev.Data) },
+			SessionID:  s.ID,
+		}
+		results := dispatcher.ExecuteAll(ctx, tcs, s.ProviderProfile.SupportsParallelToolCalls())
+		s.History = append(s.History, Turn{Kind: TurnTools, Tools: &ToolResultsTurn{Results: results, Timestamp: now()}})
+
+		s.drainSteering()
+
+		if s.Config.EnableLoopDetection && detectLoop(s.History, s.Config.LoopDetectionWindow) {
+			warn := fmt.Sprintf("Loop detected: the last %d tool calls follow a repeating pattern. Try a different approach.", s.Config.LoopDetectionWindow)
+			s.History = append(s.History, Turn{Kind: TurnSteering, Steering: &SteeringTurn{Content: warn, Timestamp: now()}})
+			s.emit(EventLoopDetection, map[string]any{"message": warn})
+		}
+	}
+
+	// Follow-ups
+	s.mu.Lock()
+	fu := append([]string{}, s.followupQueue...)
+	s.followupQueue = nil
+	s.mu.Unlock()
+	for _, msg := range fu {
+		_, _ = s.ProcessInput(ctx, msg)
+	}
+
+	if s.State != StateClosed {
+		s.State = StateIdle
+		s.emit(EventSessionEnd, map[string]any{"state": s.State})
+	}
+	return SessionResult{ID: s.ID, State: s.State, History: s.History}, nil
+}
+
+func historyToMessages(hist []Turn) []llmsdk.Message {
+	var msgs []llmsdk.Message
+	for _, t := range hist {
+		switch t.Kind {
+		case TurnUser:
+			msgs = append(msgs, llmsdk.UserMessage(t.User.Content))
+		case TurnSteering:
+			// SteeringTurns are converted to user-role messages.
+			msgs = append(msgs, llmsdk.UserMessage(t.Steering.Content))
+		case TurnAssistant:
+			content := []llmsdk.ContentPart{}
+			if t.Assistant.Content != "" {
+				content = append(content, llmsdk.TextPart(t.Assistant.Content))
+			}
+			for _, tc := range t.Assistant.ToolCalls {
+				tcData := llmsdk.ToolCallData{ID: tc.ID, Name: tc.Name, Arguments: tc.Arguments, Type: "function"}
+				content = append(content, llmsdk.ContentPart{Kind: llmsdk.ContentToolCall, ToolCall: &tcData})
+			}
+			msgs = append(msgs, llmsdk.Message{Role: llmsdk.RoleAssistant, Content: content})
+		case TurnTools:
+			for _, r := range t.Tools.Results {
+				msgs = append(msgs, llmsdk.ToolResultMessage(r.ToolCallID, r.Content, r.IsError))
+			}
+		}
+	}
+	return msgs
+}
+
+func countTurns(hist []Turn) int {
+	n := 0
+	for _, t := range hist {
+		if t.Kind == TurnAssistant {
+			n++
+		}
+	}
+	return n
+}
+
+func detectLoop(hist []Turn, window int) bool {
+	if window <= 0 {
+		return false
+	}
+	sigs := []string{}
+	for _, t := range hist {
+		if t.Kind != TurnAssistant || t.Assistant == nil {
+			continue
+		}
+		for _, tc := range t.Assistant.ToolCalls {
+			b, _ := json.Marshal(tc.Arguments)
+			h := sha256.Sum256(append([]byte(tc.Name+":"), b...))
+			sigs = append(sigs, tc.Name+"#"+hex.EncodeToString(h[:8]))
+		}
+	}
+	if len(sigs) < window {
+		return false
+	}
+	recent := sigs[len(sigs)-window:]
+	for _, plen := range []int{1, 2, 3} {
+		if window%plen != 0 {
+			continue
+		}
+		pat := recent[:plen]
+		all := true
+		for i := plen; i < window; i += plen {
+			for j := 0; j < plen; j++ {
+				if recent[i+j] != pat[j] {
+					all = false
+					break
+				}
+			}
+			if !all {
+				break
+			}
+		}
+		if all {
+			return true
+		}
+	}
+	return false
+}
