+	State   SessionState `json:"state"`
+	History []Turn       `json:"history"`
+}
+
+func NewSession(profile ProviderProfile, env ExecutionEnvironment, client *llmsdk.Client, cfg *SessionConfig) (*Session, error) {
+	if cfg == nil {
+		def := DefaultSessionConfig()
+		cfg = &def
+	}
