+}
+
+func (s *Session) Events() <-chan SessionEvent { return s.events }
+
+func (s *Session) Close() {
+	s.mu.Lock()
+	defer s.mu.Unlock()
+	if s.State == StateClosed {
+		return
+	}
+	s.State = StateClosed
+	s.emit(EventSessionEnd, map[string]any{"state": s.State})
+	close(s.events)
+}
+
+func (s *Session) Steer(msg string) {
+	s.mu.Lock()
+	defer s.mu.Unlock()
+	s.steeringQueue = append(s.steeringQueue, msg)
+}
+
+func (s *Session) FollowUp(msg string) {
+	s.mu.Lock()
+	defer s.mu.Unlock()
+	s.followupQueue = append(s.followupQueue, msg)
+}
+
+func (s *Session) drainSteering() {
+	s.mu.Lock()
+	msgs := append([]string{}, s.steeringQueue...)
+	s.steeringQueue = nil
+	s.mu.Unlock()
+	for _, msg := range msgs {
+		s.History = append(s.History, Turn{Kind: TurnSteering, Steering: &SteeringTurn{Content: msg, Timestamp: now()}})
