+			s.emit(EventTurnLimit, map[string]any{"total_turns": countTurns(s.History)})
+			break
+		}
+		if err := ctx.Err(); err != nil {
+			s.State = StateClosed
+			s.emit(EventError, map[string]any{"error": err.Error()})
+			break
+		}
+
+		systemPrompt := s.ProviderProfile.BuildSystemPrompt(s.ExecutionEnv, DiscoverProjectDocs(s.ExecutionEnv, s.ExecutionEnv.WorkingDirectory(), s.ProviderProfile.ID()))
+		messages := historyToMessages(s.History)
+		req := llmsdk.Request{
+			Model:           s.ProviderProfile.Model(),
+			Messages:        append([]llmsdk.Message{llmsdk.SystemMessage(systemPrompt)}, messages...),
+			Tools:           s.ProviderProfile.Tools(),
+			ToolChoice:      &llmsdk.ToolChoice{Mode: "auto"},
