+func detectLoop(hist []Turn, window int) bool {
+	if window <= 0 {
+		return false
+	}
+	sigs := []string{}
+	for _, t := range hist {
+		if t.Kind != TurnAssistant || t.Assistant == nil {
+			continue
+		}
+		for _, tc := range t.Assistant.ToolCalls {
+			b, _ := json.Marshal(tc.Arguments)
+			h := sha256.Sum256(append([]byte(tc.Name+":"), b...))
+			sigs = append(sigs, tc.Name+"#"+hex.EncodeToString(h[:8]))
+		}
+	}
+	if len(sigs) < window {
+		return false
+	}
+	recent := sigs[len(sigs)-window:]
+	for _, plen := range []int{1, 2, 3} {
+		if window%plen != 0 {
+			continue
+		}
+		pat := recent[:plen]
+		all := true
+		for i := plen; i < window; i += plen {
+			for j := 0; j < plen; j++ {
+				if recent[i+j] != pat[j] {
+					all = false
+					break
+				}
+			}
+			if !all {
+				break
+			}
+		}
+		if all {
+			return true
+		}
+	}
+	return false
+}
