+func (s *Session) emit(kind EventKind, data map[string]any) {
+	select {
+	case s.events <- SessionEvent{Kind: kind, Timestamp: now(), SessionID: s.ID, Data: data}:
+	default:
+		// drop if the buffer is full
+	}
+}
