+func now() time.Time { return time.Now().UTC() }
+
+func strPtr(s string) *string { return &s }
+
+func newSessionID() string {
+	// Stable-enough unique ID for tests (time-based).
+	return fmt.Sprintf("sess_%d", time.Now().UnixNano())
+}
