+package agent
+
+import (
+	"bufio"
+	"errors"
+	"fmt"
+	"os"
+	"path/filepath"
+	"strings"
+)
+
+func EditFile(env ExecutionEnvironment, path, oldString, newString string) (any, error) {
+	if strings.TrimSpace(oldString) == "" {
+		return nil, errors.New("old_string must be non-empty")
+	}
+	content, err := env.ReadFile(path, nil, nil)
+	if err != nil {
+		return nil, err
+	}
+	count := strings.Count(content, oldString)
+	if count == 0 {
+		return nil, fmt.Errorf("old_string not found in %s", path)
+	}
+	if count > 1 {
+		return nil, fmt.Errorf("old_string must be unique in %s (found %d occurrences)", path, count)
+	}
+	updated := strings.Replace(content, oldString, newString, 1)
+	if err := env.WriteFile(path, updated); err != nil {
+		return nil, err
+	}
+	return fmt.Sprintf("edited %s", path), nil
+}
+
+type PatchOp struct {
+	Op   string `json:"op"`
+	Path string `json:"path"`
+}
+
+func ApplyPatchV4A(env ExecutionEnvironment, patch string) (any, error) {
+	sc := bufio.NewScanner(strings.NewReader(patch))
+	sc.Buffer(make([]byte, 0, 64*1024), 8*1024*1024)
+
+	readLine := func() (string, bool) {
+		if !sc.Scan() {
+			return "", false
+		}
+		return sc.Text(), true
+	}
+
+	line, ok := readLine()
+	if !ok || strings.TrimSpace(line) != "*** Begin Patch" {
+		return nil, errors.New("patch must start with *** Begin Patch")
+	}
+
+	var ops []PatchOp
+	var curHeader string
+	var curPath string
+	var moveTo string
+	var contentLines []string
+	var updateBlocks [][]string
+
+	flush := func() error {
+		if curHeader == "" {
+			return nil
+		}
+		switch curHeader {
+		case "add":
+			var b strings.Builder
+			for i, l := range contentLines {
+				if strings.HasPrefix(l, "+") {
+					l = strings.TrimPrefix(l, "+")
+				}
+				if i > 0 {
+					b.WriteString("\n")
+				}
+				b.WriteString(l)
+			}
+			if err := env.WriteFile(curPath, b.String()); err != nil {
+				return err
+			}
+			ops = append(ops, PatchOp{Op: "add", Path: curPath})
+		case "delete":
+			// Best-effort delete for local env
+			if le, ok := env.(*LocalExecutionEnvironment); ok {
+				_ = os.Remove(le.abs(curPath))
+			} else {
+				// no delete interface; overwrite empty
+				_ = env.WriteFile(curPath, "")
+			}
+			ops = append(ops, PatchOp{Op: "delete", Path: curPath})
+		case "update":
+			if err := applyUpdateBlocks(env, curPath, updateBlocks); err != nil {
+				return err
+			}
+			finalPath := curPath
+			if moveTo != "" {
+				if le, ok := env.(*LocalExecutionEnvironment); ok {
+					oldAbs := le.abs(curPath)
+					newAbs := le.abs(moveTo)
+					if err := os.MkdirAll(filepath.Dir(newAbs), 0o755); err != nil {
+						return err
+					}
+					if err := os.Rename(oldAbs, newAbs); err != nil {
+						return err
+					}
+					finalPath = moveTo
+				}
+			}
+			ops = append(ops, PatchOp{Op: "update", Path: finalPath})
+		default:
+			return fmt.Errorf("unknown patch header: %s", curHeader)
+		}
+		curHeader, curPath, moveTo = "", "", ""
+		contentLines = nil
+		updateBlocks = nil
+		return nil
+	}
+
+	for sc.Scan() {
+		line := sc.Text()
+		if strings.TrimSpace(line) == "*** End Patch" {
+			break
+		}
+		if strings.HasPrefix(line, "*** Add File: ") {
+			if err := flush(); err != nil {
+				return nil, err
+			}
+			curHeader = "add"
+			curPath = strings.TrimSpace(strings.TrimPrefix(line, "*** Add File: "))
+			continue
+		}
+		if strings.HasPrefix(line, "*** Delete File: ") {
+			if err := flush(); err != nil {
+				return nil, err
+			}
+			curHeader = "delete"
+			curPath = strings.TrimSpace(strings.TrimPrefix(line, "*** Delete File: "))
+			continue
+		}
+		if strings.HasPrefix(line, "*** Update File: ") {
+			if err := flush(); err != nil {
+				return nil, err
+			}
+			curHeader = "update"
+			curPath = strings.TrimSpace(strings.TrimPrefix(line, "*** Update File: "))
+			continue
+		}
+		if strings.HasPrefix(line, "*** Move to: ") {
+			moveTo = strings.TrimSpace(strings.TrimPrefix(line, "*** Move to: "))
+			continue
+		}
+
+		switch curHeader {
+		case "add":
+			contentLines = append(contentLines, line)
+		case "update":
+			if strings.HasPrefix(line, "@@") {
+				updateBlocks = append(updateBlocks, []string{})
+				continue
+			}
+			if len(updateBlocks) == 0 {
+				updateBlocks = append(updateBlocks, []string{})
+			}
+			updateBlocks[len(updateBlocks)-1] = append(updateBlocks[len(updateBlocks)-1], line)
+		case "delete":
+			// nothing
+		default:
+			// ignore
+		}
+	}
+	if err := sc.Err(); err != nil {
+		return nil, err
+	}
+	if err := flush(); err != nil {
+		return nil, err
+	}
+	return ops, nil
+}
+
+func applyUpdateBlocks(env ExecutionEnvironment, path string, blocks [][]string) error {
+	orig, err := env.ReadFile(path, nil, nil)
+	if err != nil {
+		return err
+	}
+	lines := strings.Split(orig, "\n")
+	for _, blk := range blocks {
+		oldChunk := []string{}
+		newChunk := []string{}
+		for _, l := range blk {
+			if l == "" {
+				continue
+			}
+			prefix := l[0]
+			body := ""
+			if len(l) > 1 {
+				body = l[1:]
+			}
+			switch prefix {
+			case ' ':
+				oldChunk = append(oldChunk, body)
+				newChunk = append(newChunk, body)
+			case '-':
+				oldChunk = append(oldChunk, body)
+			case '+':
+				newChunk = append(newChunk, body)
+			default:
+				// ignore
+			}
+		}
+		if len(oldChunk) == 0 {
+			// pure insertion at start
+			lines = append(newChunk, lines...)
+			continue
+		}
+		idx := indexOfChunk(lines, oldChunk)
+		if idx < 0 {
+			return fmt.Errorf("failed to apply patch to %s: context not found", path)
+		}
+		lines = append(append(lines[:idx], newChunk...), lines[idx+len(oldChunk):]...)
+	}
+	return env.WriteFile(path, strings.Join(lines, "\n"))
+}
+
+func indexOfChunk(haystack []string, needle []string) int {
+	if len(needle) == 0 {
+		return 0
+	}
+	for i := 0; i+len(needle) <= len(haystack); i++ {
+		match := true
+		for j := 0; j < len(needle); j++ {
+			if haystack[i+j] != needle[j] {
+				match = false
+				break
+			}
+		}
+		if match {
+			return i
+		}
+	}
+	return -1
+}
+
*** End Patch

