+package attractor
+
+import (
+	"fmt"
+	"strings"
+	"unicode"
+)
+
+type tokenType string
+
+const (
+	tokEOF      tokenType = "eof"
+	tokIdent    tokenType = "ident"
+	tokString   tokenType = "string"
+	tokNumber   tokenType = "number"
+	tokBool     tokenType = "bool"
+	tokLBrace   tokenType = "{"
+	tokRBrace   tokenType = "}"
+	tokLBracket tokenType = "["
+	tokRBracket tokenType = "]"
+	tokEqual    tokenType = "="
+	tokColon    tokenType = ":"
+	tokComma    tokenType = ","
+	tokSemi     tokenType = ";"
+	tokArrow    tokenType = "->"
+)
+
+type token struct {
+	typ tokenType
+	lit string
+	pos int
+}
+
+type lexer struct {
+	src []rune
+	i   int
+}
+
+func newLexer(s string) *lexer {
+	return &lexer{src: []rune(stripComments(s))}
+}
+
+func (l *lexer) peek() rune {
+	if l.i >= len(l.src) {
+		return 0
+	}
+	return l.src[l.i]
+}
+
+func (l *lexer) next() rune {
+	if l.i >= len(l.src) {
+		return 0
+	}
+	ch := l.src[l.i]
+	l.i++
+	return ch
+}
+
+func (l *lexer) skipWS() {
+	for unicode.IsSpace(l.peek()) {
+		l.next()
+	}
+}
+
+func (l *lexer) lex() (token, error) {
+	l.skipWS()
+	start := l.i
+	ch := l.peek()
+	if ch == 0 {
+		return token{typ: tokEOF, pos: l.i}, nil
+	}
+	switch ch {
+	case '{':
+		l.next()
+		return token{typ: tokLBrace, lit: "{", pos: start}, nil
+	case '}':
+		l.next()
+		return token{typ: tokRBrace, lit: "}", pos: start}, nil
+	case '[':
+		l.next()
+		return token{typ: tokLBracket, lit: "[", pos: start}, nil
+	case ']':
+		l.next()
+		return token{typ: tokRBracket, lit: "]", pos: start}, nil
+	case '=':
+		l.next()
+		return token{typ: tokEqual, lit: "=", pos: start}, nil
+	case ':':
+		l.next()
+		return token{typ: tokColon, lit: ":", pos: start}, nil
+	case ',':
+		l.next()
+		return token{typ: tokComma, lit: ",", pos: start}, nil
+	case ';':
+		l.next()
+		return token{typ: tokSemi, lit: ";", pos: start}, nil
+	case '-':
+		l.next()
+		if l.peek() == '>' {
+			l.next()
+			return token{typ: tokArrow, lit: "->", pos: start}, nil
+		}
+		return token{}, fmt.Errorf("unexpected '-' at %d", start)
+	case '"':
+		s, err := l.lexString()
+		return token{typ: tokString, lit: s, pos: start}, err
+	}
+
+	if isIdentStart(ch) {
+		ident := l.lexIdent()
+		if ident == "true" || ident == "false" {
+			return token{typ: tokBool, lit: ident, pos: start}, nil
+		}
+		return token{typ: tokIdent, lit: ident, pos: start}, nil
+	}
+	if unicode.IsDigit(ch) || ch == '-' {
+		num := l.lexNumberOrDuration()
+		return token{typ: tokNumber, lit: num, pos: start}, nil
+	}
+
+	return token{}, fmt.Errorf("unexpected character %q at %d", ch, start)
+}
+
+func isIdentStart(ch rune) bool { return unicode.IsLetter(ch) || ch == '_' }
+func isIdentPart(ch rune) bool { return unicode.IsLetter(ch) || unicode.IsDigit(ch) || ch == '_' || ch == '.' }
+
+func (l *lexer) lexIdent() string {
+	var b strings.Builder
+	for isIdentPart(l.peek()) {
+		b.WriteRune(l.next())
+	}
+	return b.String()
+}
+
+func (l *lexer) lexString() (string, error) {
+	// consume opening quote
+	if l.next() != '"' {
+		return "", fmt.Errorf("expected string")
+	}
+	var b strings.Builder
+	for {
+		ch := l.next()
+		if ch == 0 {
+			return "", fmt.Errorf("unterminated string")
+		}
+		if ch == '"' {
+			break
+		}
+		if ch == '\\' {
+			n := l.next()
+			switch n {
+			case '"':
+				b.WriteRune('"')
+			case 'n':
+				b.WriteRune('\n')
+			case 't':
+				b.WriteRune('\t')
+			case '\\':
+				b.WriteRune('\\')
+			default:
+				b.WriteRune(n)
+			}
+			continue
+		}
+		b.WriteRune(ch)
+	}
+	return b.String(), nil
+}
+
+func (l *lexer) lexNumberOrDuration() string {
+	var b strings.Builder
+	if l.peek() == '-' {
+		b.WriteRune(l.next())
+	}
+	for unicode.IsDigit(l.peek()) {
+		b.WriteRune(l.next())
+	}
+	if l.peek() == '.' {
+		b.WriteRune(l.next())
+		for unicode.IsDigit(l.peek()) {
+			b.WriteRune(l.next())
+		}
+	}
+	// optional duration suffix
+	if unicode.IsLetter(l.peek()) {
+		for unicode.IsLetter(l.peek()) {
+			b.WriteRune(l.next())
+		}
+	}
+	return b.String()
+}
+
+func stripComments(src string) string {
+	// Remove // and /* */ comments while preserving strings.
+	var out strings.Builder
+	inStr := false
+	for i := 0; i < len(src); i++ {
+		ch := src[i]
+		if inStr {
+			out.WriteByte(ch)
+			if ch == '\\' && i+1 < len(src) {
+				i++
+				out.WriteByte(src[i])
+				continue
+			}
+			if ch == '"' {
+				inStr = false
+			}
+			continue
+		}
+		if ch == '"' {
+			inStr = true
+			out.WriteByte(ch)
+			continue
+		}
+		if ch == '/' && i+1 < len(src) && src[i+1] == '/' {
+			for i < len(src) && src[i] != '\n' {
+				i++
+			}
+			if i < len(src) {
+				out.WriteByte('\n')
+			}
+			continue
+		}
+		if ch == '/' && i+1 < len(src) && src[i+1] == '*' {
+			i += 2
+			for i+1 < len(src) && !(src[i] == '*' && src[i+1] == '/') {
+				i++
+			}
+			i++ // skip '/'
+			continue
+		}
+		out.WriteByte(ch)
+	}
+	return out.String()
+}
+
*** End Patch

