+	if isIdentStart(ch) {
+		ident := l.lexIdent()
+		if ident == "true" || ident == "false" {
+			return token{typ: tokBool, lit: ident, pos: start}, nil
+		}
+		return token{typ: tokIdent, lit: ident, pos: start}, nil
+	}
