+func isIdentStart(ch rune) bool { return unicode.IsLetter(ch) || ch == '_' }
+func isIdentPart(ch rune) bool { return unicode.IsLetter(ch) || unicode.IsDigit(ch) || ch == '_' || ch == '.' }
+
+func (l *lexer) lexIdent() string {
+	var b strings.Builder
+	for isIdentPart(l.peek()) {
+		b.WriteRune(l.next())
+	}
+	return b.String()
+}
+
+func (l *lexer) lexString() (string, error) {
+	// consume opening quote
+	if l.next() != '"' {
+		return "", fmt.Errorf("expected string")
+	}
+	var b strings.Builder
+	for {
+		ch := l.next()
+		if ch == 0 {
+			return "", fmt.Errorf("unterminated string")
+		}
+		if ch == '"' {
+			break
+		}
+		if ch == '\\' {
+			n := l.next()
+			switch n {
+			case '"':
+				b.WriteRune('"')
+			case 'n':
+				b.WriteRune('\n')
+			case 't':
+				b.WriteRune('\t')
+			case '\\':
+				b.WriteRune('\\')
+			default:
+				b.WriteRune(n)
+			}
+			continue
+		}
+		b.WriteRune(ch)
+	}
+	return b.String(), nil
+}
+
+func (l *lexer) lexNumberOrDuration() string {
+	var b strings.Builder
+	if l.peek() == '-' {
+		b.WriteRune(l.next())
+	}
+	for unicode.IsDigit(l.peek()) {
+		b.WriteRune(l.next())
+	}
+	if l.peek() == '.' {
+		b.WriteRune(l.next())
+		for unicode.IsDigit(l.peek()) {
+			b.WriteRune(l.next())
+		}
+	}
+	// optional duration suffix
+	if unicode.IsLetter(l.peek()) {
+		for unicode.IsLetter(l.peek()) {
+			b.WriteRune(l.next())
+		}
+	}
+	return b.String()
+}
+
+func stripComments(src string) string {
+	// Remove // and /* */ comments while preserving strings.
+	var out strings.Builder
+	inStr := false
+	for i := 0; i < len(src); i++ {
+		ch := src[i]
+		if inStr {
+			out.WriteByte(ch)
+			if ch == '\\' && i+1 < len(src) {
+				i++
+				out.WriteByte(src[i])
+				continue
+			}
+			if ch == '"' {
+				inStr = false
+			}
+			continue
+		}
+		if ch == '"' {
+			inStr = true
+			out.WriteByte(ch)
+			continue
+		}
+		if ch == '/' && i+1 < len(src) && src[i+1] == '/' {
+			for i < len(src) && src[i] != '\n' {
+				i++
+			}
+			if i < len(src) {
+				out.WriteByte('\n')
+			}
+			continue
+		}
+		if ch == '/' && i+1 < len(src) && src[i+1] == '*' {
+			i += 2
+			for i+1 < len(src) && !(src[i] == '*' && src[i+1] == '/') {
+				i++
+			}
+			i++ // skip '/'
+			continue
+		}
+		out.WriteByte(ch)
+	}
+	return out.String()
+}
