+func (p *parser) parseAttrBlock() (map[string]AttrValue, error) {
+	if _, err := p.expect(tokLBracket); err != nil {
+		return nil, err
+	}
+	attrs := map[string]AttrValue{}
+	for p.tok.typ != tokRBracket && p.tok.typ != tokEOF {
+		if p.tok.typ != tokIdent {
+			return nil, fmt.Errorf("expected attribute key, got %s", p.tok.typ)
+		}
+		key := p.tok.lit
+		_ = p.next()
+		if _, err := p.expect(tokEqual); err != nil {
+			return nil, err
+		}
+		val, err := p.parseValue()
+		if err != nil {
+			return nil, err
+		}
+		attrs[key] = val
+		if p.tok.typ == tokComma {
+			_ = p.next()
+			continue
+		}
+	}
+	if _, err := p.expect(tokRBracket); err != nil {
+		return nil, err
+	}
+	return attrs, nil
