+	if _, err := p.expect(tokRBrace); err != nil {
+		return err
+	}
+	p.popScope()
+	return nil
+}
+
+func (p *parser) parseNodeOrEdgeOrAttrDecl() error {
+	// starts with Identifier
+	first := p.tok.lit
+	_ = p.next()
+	if p.tok.typ == tokEqual {
+		// graph attr decl in current scope
+		_ = p.next()
+		val, err := p.parseValue()
+		if err != nil {
+			return err
+		}
+		// graph-level attrs always stored on graph; subgraph label used for class derivation
+		if first == "label" {
+			p.applyDerivedClass(val.Str)
+		}
+		p.g.GraphAttrs[first] = val
+		return nil
+	}
+	if p.tok.typ == tokArrow {
+		// edge statement with chaining
+		nodes := []string{first}
+		for p.tok.typ == tokArrow {
+			_ = p.next()
+			idTok, err := p.expect(tokIdent)
+			if err != nil {
+				return err
+			}
+			nodes = append(nodes, idTok.lit)
+		}
+		var attrs map[string]AttrValue
+		if p.tok.typ == tokLBracket {
+			a, err := p.parseAttrBlock()
+			if err != nil {
+				return err
+			}
+			attrs = a
+		} else {
+			attrs = map[string]AttrValue{}
+		}
+		merged := mergeAttrs(p.scope().edgeDefaults, attrs)
+		for i := 0; i < len(nodes)-1; i++ {
+			p.g.Edges = append(p.g.Edges, &Edge{From: nodes[i], To: nodes[i+1], Attrs: cloneAttrs(merged)})
+		}
+		return nil
+	}
+	// node statement
+	attrs := map[string]AttrValue{}
+	if p.tok.typ == tokLBracket {
+		a, err := p.parseAttrBlock()
+		if err != nil {
+			return err
+		}
+		attrs = a
+	}
+	merged := mergeAttrs(p.scope().nodeDefaults, attrs)
+	merged = applyScopeClasses(merged, p.scope().classes)
+	n := p.g.Nodes[first]
+	if n == nil {
+		n = &Node{ID: first, Attrs: map[string]AttrValue{}}
+		p.g.Nodes[first] = n
+	}
+	for k, v := range merged {
+		n.Attrs[k] = v
+	}
+	p.scope().nodeIDs = append(p.scope().nodeIDs, first)
+	return nil
+}
+
+func mergeAttrs(base, overrides map[string]AttrValue) map[string]AttrValue {
+	out := cloneAttrs(base)
+	for k, v := range overrides {
+		out[k] = v
+	}
+	return out
+}
+
+func applyScopeClasses(attrs map[string]AttrValue, classes []string) map[string]AttrValue {
+	if len(classes) == 0 {
+		return attrs
+	}
+	existing := ""
+	if v, ok := attrs["class"]; ok {
+		existing = v.Str
+	}
+	all := []string{}
+	if existing != "" {
+		for _, c := range strings.Split(existing, ",") {
+			c = strings.TrimSpace(c)
+			if c != "" {
+				all = append(all, c)
+			}
+		}
+	}
+	all = append(all, classes...)
+	seen := map[string]bool{}
+	final := []string{}
+	for _, c := range all {
+		if c == "" || seen[c] {
+			continue
+		}
+		seen[c] = true
+		final = append(final, c)
+	}
+	attrs["class"] = AttrValue{Type: ValueString, Raw: strings.Join(final, ","), Str: strings.Join(final, ",")}
+	return attrs
+}
+
+func (p *parser) applyDerivedClass(label string) {
+	c := deriveClassFromLabel(label)
+	if c == "" {
+		return
+	}
+	sc := p.scope()
+	sc.classes = append(sc.classes, c)
+	// retroactively apply to already parsed nodes in this scope
+	for _, id := range sc.nodeIDs {
+		n := p.g.Nodes[id]
+		if n == nil {
+			continue
+		}
+		n.Attrs = applyScopeClasses(n.Attrs, []string{c})
+	}
+}
+
+func deriveClassFromLabel(label string) string {
+	s := strings.ToLower(strings.TrimSpace(label))
+	if s == "" {
+		return ""
+	}
+	s = strings.ReplaceAll(s, " ", "-")
+	var b strings.Builder
+	for _, r := range s {
+		if (r >= 'a' && r <= 'z') || (r >= '0' && r <= '9') || r == '-' {
+			b.WriteRune(r)
+		}
+	}
+	return b.String()
+}
+
+func (p *parser) parseAttrBlock() (map[string]AttrValue, error) {
+	if _, err := p.expect(tokLBracket); err != nil {
+		return nil, err
+	}
+	attrs := map[string]AttrValue{}
+	for p.tok.typ != tokRBracket && p.tok.typ != tokEOF {
+		if p.tok.typ != tokIdent {
+			return nil, fmt.Errorf("expected attribute key, got %s", p.tok.typ)
+		}
+		key := p.tok.lit
+		_ = p.next()
+		if _, err := p.expect(tokEqual); err != nil {
+			return nil, err
+		}
+		val, err := p.parseValue()
+		if err != nil {
+			return nil, err
+		}
+		attrs[key] = val
+		if p.tok.typ == tokComma {
+			_ = p.next()
+			continue
+		}
+	}
+	if _, err := p.expect(tokRBracket); err != nil {
+		return nil, err
+	}
+	return attrs, nil
+}
+
+func (p *parser) parseValue() (AttrValue, error) {
+	switch p.tok.typ {
+	case tokString:
+		s := p.tok.lit
+		_ = p.next()
+		return AttrValue{Type: ValueString, Raw: s, Str: s}, nil
+	case tokBool:
+		raw := p.tok.lit
+		_ = p.next()
+		b := raw == "true"
+		return AttrValue{Type: ValueBool, Raw: raw, Bool: &b}, nil
+	case tokNumber:
+		raw := p.tok.lit
+		_ = p.next()
+		// duration?
+		if strings.HasSuffix(raw, "ms") || strings.HasSuffix(raw, "s") || strings.HasSuffix(raw, "m") || strings.HasSuffix(raw, "h") || strings.HasSuffix(raw, "d") {
+			conv := raw
+			if strings.HasSuffix(raw, "d") {
+				// convert days to hours
+				n, err := strconv.ParseInt(strings.TrimSuffix(raw, "d"), 10, 64)
+				if err != nil {
+					return AttrValue{}, err
+				}
+				conv = fmt.Sprintf("%dh", n*24)
+			}
+			return AttrValue{Type: ValueDuration, Raw: conv, Str: conv}, nil
+		}
+		if strings.Contains(raw, ".") {
+			f, err := strconv.ParseFloat(raw, 64)
+			if err != nil {
+				return AttrValue{}, err
+			}
+			return AttrValue{Type: ValueFloat, Raw: raw, Float: &f}, nil
+		}
+		i, err := strconv.ParseInt(raw, 10, 64)
+		if err != nil {
+			return AttrValue{}, err
+		}
+		return AttrValue{Type: ValueInt, Raw: raw, Int: &i}, nil
+	case tokIdent:
+		// permissive: treat bare identifiers as strings for values like shape=box.
+		raw := p.tok.lit
+		_ = p.next()
+		return AttrValue{Type: ValueString, Raw: raw, Str: raw}, nil
+	default:
+		return AttrValue{}, fmt.Errorf("unexpected value token %s (%q)", p.tok.typ, p.tok.lit)
+	}
+}
