+func selectorMatches(sel stylesheetSelector, id, shape string, classes map[string]bool) bool {
+	switch sel.Kind {
+	case selUniversal:
+		return true
+	case selID:
+		return sel.Name == id
+	case selClass:
+		return classes[sel.Name]
+	case selShape:
+		return sel.Name == shape
