+package attractor
+
+import (
+	"fmt"
+)
+
+type Severity string
+
+const (
+	SeverityError   Severity = "ERROR"
+	SeverityWarning Severity = "WARNING"
+	SeverityInfo    Severity = "INFO"
+)
+
+type Diagnostic struct {
+	Rule     string     `json:"rule"`
+	Severity Severity   `json:"severity"`
+	Message  string     `json:"message"`
+	NodeID   *string    `json:"node_id,omitempty"`
+	Edge     *[2]string `json:"edge,omitempty"`
+	Fix      *string    `json:"fix,omitempty"`
+}
+
+func Validate(g *Graph) []Diagnostic {
+	var diags []Diagnostic
+
+	// stylesheet syntax
+	if v, ok := g.GraphAttrs["model_stylesheet"]; ok && v.Str != "" {
+		if _, err := ParseStylesheet(v.Str); err != nil {
+			msg := fmt.Sprintf("model_stylesheet parse error: %v", err)
+			diags = append(diags, Diagnostic{Rule: "stylesheet_syntax", Severity: SeverityError, Message: msg})
+		}
+	}
+
+	starts := findNodesByStart(g)
+	if len(starts) != 1 {
+		msg := fmt.Sprintf("expected exactly one start node (shape=Mdiamond or id=start), found %d", len(starts))
+		diags = append(diags, Diagnostic{Rule: "start_node", Severity: SeverityError, Message: msg})
+	}
+	exits := findNodesByExit(g)
+	if len(exits) != 1 {
+		msg := fmt.Sprintf("expected exactly one exit node (shape=Msquare or id=exit/end), found %d", len(exits))
+		diags = append(diags, Diagnostic{Rule: "terminal_node", Severity: SeverityError, Message: msg})
+	}
+
+	// edge targets exist
+	for _, e := range g.Edges {
+		if g.Nodes[e.From] == nil || g.Nodes[e.To] == nil {
+			edge := [2]string{e.From, e.To}
+			diags = append(diags, Diagnostic{Rule: "edge_target_exists", Severity: SeverityError, Message: "edge references missing node", Edge: &edge})
+		}
+		// condition syntax
+		if cond := e.Condition(); cond != "" {
+			if err := ValidateConditionSyntax(cond); err != nil {
+				edge := [2]string{e.From, e.To}
+				diags = append(diags, Diagnostic{Rule: "condition_syntax", Severity: SeverityError, Message: err.Error(), Edge: &edge})
+			}
+		}
+	}
+
+	if len(starts) == 1 {
+		start := starts[0]
+		if len(g.IncomingEdges(start.ID)) > 0 {
+			id := start.ID
+			diags = append(diags, Diagnostic{Rule: "start_no_incoming", Severity: SeverityError, Message: "start node has incoming edges", NodeID: &id})
+		}
+		// reachability
+		reach := reachableFrom(g, start.ID)
+		for id := range g.Nodes {
+			if !reach[id] {
+				nid := id
+				diags = append(diags, Diagnostic{Rule: "reachability", Severity: SeverityError, Message: "node is not reachable from start", NodeID: &nid})
+			}
+		}
+	}
+	if len(exits) == 1 {
+		exit := exits[0]
+		if len(g.OutgoingEdges(exit.ID)) > 0 {
+			id := exit.ID
+			diags = append(diags, Diagnostic{Rule: "exit_no_outgoing", Severity: SeverityError, Message: "exit node has outgoing edges", NodeID: &id})
+		}
+	}
+
+	// prompt on llm nodes (warning)
+	for _, n := range g.Nodes {
+		if handlerTypeForNode(n) == "codergen" {
+			prompt := ""
+			if v, ok := n.Attrs["prompt"]; ok {
+				prompt = v.Str
+			}
+			if prompt == "" && n.Label() == "" {
+				id := n.ID
+				diags = append(diags, Diagnostic{Rule: "prompt_on_llm_nodes", Severity: SeverityWarning, Message: "codergen node missing prompt/label", NodeID: &id})
+			}
+		}
+	}
+
+	return diags
+}
+
+func ValidateOrRaise(g *Graph) ([]Diagnostic, error) {
+	diags := Validate(g)
+	for _, d := range diags {
+		if d.Severity == SeverityError {
+			return diags, fmt.Errorf("validation failed: %s", d.Message)
+		}
+	}
+	return diags, nil
+}
+
+func findNodesByStart(g *Graph) []*Node {
+	var out []*Node
+	for _, n := range g.Nodes {
+		if n.Shape() == "Mdiamond" || n.ID == "start" || n.ID == "Start" {
+			out = append(out, n)
+		}
+	}
+	return out
+}
+
+func findNodesByExit(g *Graph) []*Node {
+	var out []*Node
+	for _, n := range g.Nodes {
+		if n.Shape() == "Msquare" || n.ID == "exit" || n.ID == "end" || n.ID == "Exit" || n.ID == "End" {
+			out = append(out, n)
+		}
+	}
+	return out
+}
+
+func reachableFrom(g *Graph, start string) map[string]bool {
+	seen := map[string]bool{start: true}
+	queue := []string{start}
+	for len(queue) > 0 {
+		cur := queue[0]
+		queue = queue[1:]
+		for _, e := range g.OutgoingEdges(cur) {
+			if !seen[e.To] {
+				seen[e.To] = true
+				queue = append(queue, e.To)
+			}
+		}
+	}
+	return seen
+}
+
