+package attractor
+
+import (
+	"context"
+	"encoding/json"
+	"errors"
+	"fmt"
+	"math"
+	"math/rand"
+	"os"
+	"path/filepath"
+	"sort"
+	"strings"
+	"time"
+)
+
+type Handler interface {
+	Execute(ctx context.Context, node *Node, ctxKV Context, g *Graph, logsRoot string) (Outcome, error)
+}
+
+type HandlerRegistry struct {
+	handlers map[string]Handler
+	defaultH Handler
+}
+
+func NewHandlerRegistry(defaultHandler Handler) *HandlerRegistry {
+	return &HandlerRegistry{handlers: map[string]Handler{}, defaultH: defaultHandler}
+}
+
+func (r *HandlerRegistry) Register(typeString string, h Handler) {
+	r.handlers[typeString] = h
+}
+
+func (r *HandlerRegistry) Resolve(n *Node) Handler {
+	if n.Type() != "" {
+		if h, ok := r.handlers[n.Type()]; ok {
+			return h
+		}
+	}
+	shapeType := shapeToType(n.Shape())
+	if h, ok := r.handlers[shapeType]; ok {
+		return h
+	}
+	return r.defaultH
+}
+
+func (r *HandlerRegistry) Types() []string {
+	out := make([]string, 0, len(r.handlers))
+	for k := range r.handlers {
+		out = append(out, k)
+	}
+	sort.Strings(out)
+	return out
+}
+
+func shapeToType(shape string) string {
+	switch shape {
+	case "Mdiamond":
+		return "start"
+	case "Msquare":
+		return "exit"
+	case "box":
+		return "codergen"
+	case "hexagon":
+		return "wait.human"
+	case "diamond":
+		return "conditional"
+	case "component":
+		return "parallel"
+	case "tripleoctagon":
+		return "parallel.fan_in"
+	case "parallelogram":
+		return "tool"
+	case "house":
+		return "stack.manager_loop"
+	default:
+		return "codergen"
+	}
+}
+
+func handlerTypeForNode(n *Node) string {
+	if n.Type() != "" {
+		return n.Type()
+	}
+	return shapeToType(n.Shape())
+}
+
+type CodergenBackend interface {
+	Run(ctx context.Context, node *Node, prompt string, ctxKV Context) (string, error)
+}
+
+type EngineConfig struct {
+	LogsRoot string `json:"logs_root"`
+}
+
+type Checkpoint struct {
+	CurrentNode    string            `json:"current_node"`
+	CompletedNodes []string          `json:"completed_nodes"`
+	Context        map[string]string `json:"context"`
+	RetryCounts    map[string]int    `json:"retry_counts"`
+}
+
+type ExecutionResult struct {
+	Outcome        string            `json:"outcome"`
+	CompletedNodes []string          `json:"completed_nodes"`
