+func findStartNodeOrError(g *Graph) *Node {
+	for _, n := range g.Nodes {
+		if n.Shape() == "Mdiamond" {
+			return n
+		}
+	}
+	if n := g.Nodes["start"]; n != nil {
+		return n
+	}
+	if n := g.Nodes["Start"]; n != nil {
