+
+func checkGoalGates(g *Graph, outcomes map[string]Outcome) (bool, *Node) {
+	for id, o := range outcomes {
+		n := g.Nodes[id]
+		if n == nil {
+			continue
+		}
+		if n.Attrs["goal_gate"].AsBool(false) {
+			if o.Status != "success" && o.Status != "partial_success" {
+				return false, n
+			}
+		}
+	}
+	return true, nil
+}
+
+func resolveRetryTarget(failed *Node, g *Graph) string {
+	if failed != nil {
+		if v, ok := failed.Attrs["retry_target"]; ok && v.Str != "" {
+			return v.Str
+		}
+		if v, ok := failed.Attrs["fallback_retry_target"]; ok && v.Str != "" {
+			return v.Str
+		}
+	}
+	if v, ok := g.GraphAttrs["retry_target"]; ok && v.Str != "" {
+		return v.Str
+	}
+	if v, ok := g.GraphAttrs["fallback_retry_target"]; ok && v.Str != "" {
+		return v.Str
+	}
+	return ""
+}
+
+func selectEdge(g *Graph, node *Node, outcome Outcome, ctxKV map[string]string) *Edge {
+	edges := g.OutgoingEdges(node.ID)
+	if len(edges) == 0 {
+		return nil
+	}
+	ctx := Context(ctxKV)
+
+	// Step 1: condition matching edges (only those with condition)
+	condMatched := []*Edge{}
+	for _, e := range edges {
+		if strings.TrimSpace(e.Condition()) == "" {
+			continue
+		}
+		if EvaluateCondition(e.Condition(), outcome, ctx) {
+			condMatched = append(condMatched, e)
+		}
+	}
+	if len(condMatched) > 0 {
+		return bestByWeightThenLex(condMatched)
+	}
+
+	// Step 2: preferred label match
+	if outcome.PreferredLabel != "" {
+		want := NormalizeLabel(outcome.PreferredLabel)
+		for _, e := range edges {
+			if strings.TrimSpace(e.Condition()) != "" && !EvaluateCondition(e.Condition(), outcome, ctx) {
+				continue
+			}
+			if NormalizeLabel(e.Label()) == want {
+				return e
+			}
+		}
+	}
+
+	// Step 3: suggested next IDs
+	if len(outcome.SuggestedNextIDs) > 0 {
+		for _, sid := range outcome.SuggestedNextIDs {
+			for _, e := range edges {
+				if e.To == sid {
+					if strings.TrimSpace(e.Condition()) == "" || EvaluateCondition(e.Condition(), outcome, ctx) {
+						return e
+					}
+				}
+			}
+		}
+	}
+
+	// Step 4 & 5: unconditional edges weight then lexical
+	uncond := []*Edge{}
+	for _, e := range edges {
+		if strings.TrimSpace(e.Condition()) == "" {
+			uncond = append(uncond, e)
+		}
+	}
+	if len(uncond) > 0 {
+		return bestByWeightThenLex(uncond)
+	}
+	return bestByWeightThenLex(edges)
+}
+
+func bestByWeightThenLex(edges []*Edge) *Edge {
+	sort.Slice(edges, func(i, j int) bool {
+		if edges[i].Weight() != edges[j].Weight() {
+			return edges[i].Weight() > edges[j].Weight()
+		}
+		return edges[i].To < edges[j].To
+	})
+	return edges[0]
+}
+
+type RetryPolicy struct {
+	MaxAttempts int
+	InitialDelayMS int
+	BackoffFactor float64
+	MaxDelayMS int
+	Jitter bool
+}
+
+func buildRetryPolicy(node *Node, g *Graph) RetryPolicy {
+	maxRetries := 0
+	if v, ok := node.Attrs["max_retries"]; ok && v.Int != nil {
+		maxRetries = int(*v.Int)
+	} else if v, ok := g.GraphAttrs["default_max_retry"]; ok && v.Int != nil {
+		maxRetries = int(*v.Int)
+	}
+	return RetryPolicy{
+		MaxAttempts: maxRetries + 1,
+		InitialDelayMS: 200,
+		BackoffFactor: 2.0,
+		MaxDelayMS: 60000,
+		Jitter: true,
+	}
+}
+
+func delayForAttempt(attempt int, pol RetryPolicy) time.Duration {
+	delay := float64(pol.InitialDelayMS) * math.Pow(pol.BackoffFactor, float64(attempt-1))
+	if delay > float64(pol.MaxDelayMS) {
+		delay = float64(pol.MaxDelayMS)
+	}
+	if pol.Jitter {
+		delay = delay * (0.5 + rand.Float64())
+	}
+	return time.Duration(delay) * time.Millisecond
+}
+
+func executeWithRetry(ctx context.Context, h Handler, node *Node, cp *Checkpoint, g *Graph, logsRoot string) (Outcome, error) {
+	pol := buildRetryPolicy(node, g)
+	if pol.MaxAttempts < 1 {
+		pol.MaxAttempts = 1
+	}
+	for attempt := 1; attempt <= pol.MaxAttempts; attempt++ {
+		outcome, err := h.Execute(ctx, node, Context(cp.Context), g, logsRoot)
+		if err != nil {
+			if shouldRetryError(err) && attempt < pol.MaxAttempts {
+				time.Sleep(delayForAttempt(attempt, pol))
+				continue
+			}
+			return Outcome{Status: "fail", Notes: err.Error()}, nil
+		}
+		if outcome.Status == "" {
+			outcome.Status = "success"
+		}
+		if outcome.Status == "success" || outcome.Status == "partial_success" {
+			cp.RetryCounts[node.ID] = 0
+			_ = writeOutcome(logsRoot, node.ID, outcome)
+			return outcome, nil
+		}
+		if outcome.Status == "retry" {
+			if attempt < pol.MaxAttempts {
+				cp.RetryCounts[node.ID]++
+				time.Sleep(delayForAttempt(attempt, pol))
+				continue
+			}
+			if node.Attrs["allow_partial"].AsBool(false) {
+				outcome.Status = "partial_success"
+				outcome.Notes = "retries exhausted, partial accepted"
+				_ = writeOutcome(logsRoot, node.ID, outcome)
+				return outcome, nil
+			}
+			outcome.Status = "fail"
+			outcome.Notes = "max retries exceeded"
+			_ = writeOutcome(logsRoot, node.ID, outcome)
+			return outcome, nil
+		}
+		if outcome.Status == "fail" {
+			_ = writeOutcome(logsRoot, node.ID, outcome)
+			return outcome, nil
+		}
+		_ = writeOutcome(logsRoot, node.ID, outcome)
+		return outcome, nil
+	}
+	return Outcome{Status: "fail", Notes: "max retries exceeded"}, nil
+}
+
+func shouldRetryError(err error) bool {
+	var pe *errors.Error
+	_ = pe
+	// simple: retry on network-like errors
+	msg := strings.ToLower(err.Error())
+	if strings.Contains(msg, "429") || strings.Contains(msg, "rate") {
+		return true
+	}
+	if strings.Contains(msg, "timeout") || strings.Contains(msg, "tempor") || strings.Contains(msg, "unavailable") {
+		return true
+	}
+	if strings.Contains(msg, "401") || strings.Contains(msg, "403") || strings.Contains(msg, "invalid request") {
+		return false
+	}
+	return true
+}
+
+func writeOutcome(logsRoot, nodeID string, o Outcome) error {
+	dir := filepath.Join(logsRoot, nodeID)
+	if err := os.MkdirAll(dir, 0o755); err != nil {
+		return err
+	}
+	b, _ := json.MarshalIndent(o, "", "  ")
+	return os.WriteFile(filepath.Join(dir, "status.json"), b, 0o644)
+}
+
+func SaveCheckpoint(path string, cp *Checkpoint) error {
+	b, _ := json.MarshalIndent(cp, "", "  ")
+	return os.WriteFile(path, b, 0o644)
+}
+
+func LoadCheckpoint(path string) (*Checkpoint, error) {
+	b, err := os.ReadFile(path)
+	if err != nil {
+		return nil, err
+	}
+	var cp Checkpoint
+	if err := json.Unmarshal(b, &cp); err != nil {
+		return nil, err
+	}
+	if cp.Context == nil {
+		cp.Context = map[string]string{}
+	}
+	if cp.RetryCounts == nil {
+		cp.RetryCounts = map[string]int{}
+	}
+	return &cp, nil
+}
+
