+type Answer struct {
+	Value string `json:"value,omitempty"`
+	Text  string `json:"text,omitempty"`
+}
+
+type Interviewer interface {
+	Ask(q Question) Answer
+}
+
+type AutoApproveInterviewer struct{}
+
+func (a AutoApproveInterviewer) Ask(q Question) Answer {
+	switch q.Type {
+	case SingleSelect:
+		if len(q.Choices) > 0 {
+			return Answer{Value: q.Choices[0].Value}
+		}
+		return Answer{Value: ""}
+	case Confirm:
+		return Answer{Value: "yes"}
+	case FreeText:
+		return Answer{Text: ""}
+	default:
+		if len(q.Choices) > 0 {
+			return Answer{Value: q.Choices[0].Value}
+		}
+		return Answer{}
+	}
+}
+
+type QueueInterviewer struct {
+	Answers []Answer
+}
+
+func (q *QueueInterviewer) Ask(question Question) Answer {
+	if len(q.Answers) == 0 {
+		return Answer{Value: "SKIPPED"}
+	}
+	a := q.Answers[0]
+	q.Answers = q.Answers[1:]
+	return a
+}
+
+type ConsoleInterviewer struct{}
+
+func (c ConsoleInterviewer) Ask(q Question) Answer {
+	fmt.Fprintln(os.Stderr, q.Prompt)
+	if q.Type == SingleSelect && len(q.Choices) > 0 {
+		for i, ch := range q.Choices {
+			fmt.Fprintf(os.Stderr, "%d) %s\n", i+1, ch.Label)
+		}
+	}
+	fmt.Fprint(os.Stderr, "> ")
+	in := bufio.NewReader(os.Stdin)
+	line, _ := in.ReadString('\n')
+	line = strings.TrimSpace(line)
+	if q.Type == SingleSelect && len(q.Choices) > 0 {
+		// accept index
+		for i, ch := range q.Choices {
+			if line == fmt.Sprintf("%d", i+1) {
+				return Answer{Value: ch.Value}
+			}
+		}
+		// accept value
+		for _, ch := range q.Choices {
+			if line == ch.Value {
+				return Answer{Value: ch.Value}
+			}
+		}
+	}
+	return Answer{Text: line, Value: line}
+}
+
