+		lbl := e.Label()
+		if lbl == "" {
+			lbl = e.To
+		}
+		choices = append(choices, Choice{Label: lbl, Value: lbl})
+	}
+	q := Question{Type: SingleSelect, Prompt: "Select next:", Choices: choices}
+	a := interviewer.Ask(q)
+	return Outcome{Status: "success", PreferredLabel: a.Value}, nil
+}
+
+type ConditionalHandler struct{}
+
+func (h ConditionalHandler) Execute(ctx context.Context, node *Node, ctxKV Context, g *Graph, logsRoot string) (Outcome, error) {
+	_ = ctx
+	_ = node
+	_ = ctxKV
+	_ = g
+	_ = logsRoot
+	return Outcome{Status: "success", Notes: "conditional pass-through"}, nil
+}
+
+type ParallelHandler struct{}
+
+func (h ParallelHandler) Execute(ctx context.Context, node *Node, ctxKV Context, g *Graph, logsRoot string) (Outcome, error) {
+	_ = ctx
+	_ = node
+	_ = ctxKV
+	_ = g
+	_ = logsRoot
+	return Outcome{Status: "success", Notes: "parallel handler stub"}, nil
+}
+
+type FanInHandler struct{}
+
+func (h FanInHandler) Execute(ctx context.Context, node *Node, ctxKV Context, g *Graph, logsRoot string) (Outcome, error) {
+	_ = ctx
+	_ = node
+	_ = ctxKV
+	_ = g
+	_ = logsRoot
+	return Outcome{Status: "success", Notes: "fan-in handler stub"}, nil
+}
+
+type ToolHandler struct{}
+
+func (h ToolHandler) Execute(ctx context.Context, node *Node, ctxKV Context, g *Graph, logsRoot string) (Outcome, error) {
+	_ = g
+	cmd := ""
+	if v, ok := node.Attrs["tool_command"]; ok {
+		cmd = v.Str
+	}
+	if cmd == "" {
+		return Outcome{Status: "fail", Notes: "No tool_command specified"}, nil
+	}
+	timeout := 0 * time.Second
+	if v, ok := node.Attrs["timeout"]; ok && v.Type == ValueDuration {
+		timeout = v.AsDuration(0)
+	}
+	if timeout <= 0 {
+		timeout = 60 * time.Second
+	}
+	cctx, cancel := context.WithTimeout(ctx, timeout)
+	defer cancel()
+	ex := exec.CommandContext(cctx, "/bin/bash", "-lc", cmd)
+	out, err := ex.CombinedOutput()
+	stageDir := filepath.Join(logsRoot, node.ID)
+	_ = os.MkdirAll(stageDir, 0o755)
+	_ = os.WriteFile(filepath.Join(stageDir, "tool_output.txt"), out, 0o644)
+	if err != nil {
+		return Outcome{Status: "fail", Notes: err.Error()}, nil
+	}
+	ctxKV["tool.output"] = string(out)
+	return Outcome{Status: "success", ContextUpdates: map[string]string{"tool.output": string(out)}, Notes: "Tool completed: " + cmd}, nil
+}
+
+func writeJSON(path string, v any) {
+	b, _ := json.MarshalIndent(v, "", "  ")
+	_ = os.WriteFile(path, b, 0o644)
+}
+
+func mustJoin(parts ...string) string { return strings.Join(parts, "") }
+
