+	Config *agent.SessionConfig
+}
+
+func (b *AgentBackend) Run(ctx context.Context, node *Node, prompt string, ctxKV Context) (string, error) {
+	_ = ctxKV
+	provider := ""
+	if v, ok := node.Attrs["llm_provider"]; ok && v.Str != "" {
+		provider = v.Str
+	}
+	model := ""
+	if v, ok := node.Attrs["llm_model"]; ok && v.Str != "" {
+		model = v.Str
+	}
+	if provider == "" && model != "" {
+		provider = inferProviderFromModel(model)
+	}
+	if provider == "" {
+		provider = "openai"
+	}
+
+	env := b.Env
+	if env == nil {
+		env = agent.NewLocalExecutionEnvironment("")
+	}
+	client := b.Client
+	if client == nil {
+		c, err := llmsdk.DefaultClient()
+		if err != nil {
+			return "", err
+		}
+		client = c
+	}
+
+	var prof agent.ProviderProfile
+	switch provider {
+	case "anthropic":
+		prof = agent.NewAnthropicProfile(model, env)
+	case "gemini":
+		prof = agent.NewGeminiProfile(model, env)
+	default:
+		prof = agent.NewOpenAIProfile(model, env)
+	}
+
+	cfg := b.Config
+	if cfg == nil {
+		def := agent.DefaultSessionConfig()
+		cfg = &def
+	}
+	if v, ok := node.Attrs["reasoning_effort"]; ok && v.Str != "" {
+		cfg2 := *cfg
+		cfg2.ReasoningEffort = &v.Str
+		cfg = &cfg2
+	}
+	sess, err := agent.NewSession(prof, env, client, cfg)
+	if err != nil {
+		return "", err
+	}
+	res, err := sess.ProcessInput(ctx, prompt)
+	if err != nil {
+		return "", err
+	}
+	// Return the last assistant text.
+	for i := len(res.History) - 1; i >= 0; i-- {
+		if res.History[i].Kind == agent.TurnAssistant && res.History[i].Assistant != nil {
+			return res.History[i].Assistant.Content, nil
+		}
+	}
+	return "", fmt.Errorf("no assistant output")
+}
+
+func inferProviderFromModel(model string) string {
+	model = strings.ToLower(model)
+	switch {
+	case strings.HasPrefix(model, "gpt-"):
+		return "openai"
+	case strings.HasPrefix(model, "claude-"):
+		return "anthropic"
+	case strings.HasPrefix(model, "gemini-"):
+		return "gemini"
+	default:
+		return ""
+	}
+}
+
