+package main
+
+import (
+	"bufio"
+	"context"
+	"encoding/json"
+	"fmt"
+	"io"
+	"os"
+	"strings"
+	"time"
+
+	"attractorbench/pkg/agent"
+	"attractorbench/pkg/attractor"
+	"attractorbench/pkg/llmsdk"
+)
+
+func main() {
+	if len(os.Args) < 2 {
+		fmt.Fprintln(os.Stderr, "usage: conformance <subcommand>")
+		os.Exit(2)
+	}
+	cmd := os.Args[1]
+	switch cmd {
+	case "client-from-env":
+		client, err := llmsdk.ClientFromEnv()
+		if err != nil || client == nil {
+			fmt.Fprintln(os.Stderr, err)
+			os.Exit(1)
+		}
+		os.Exit(0)
+	case "complete":
+		var req llmsdk.Request
+		mustReadJSON(os.Stdin, &req)
+		client, err := llmsdk.DefaultClient()
+		if err != nil {
+			die(err)
+		}
+		resp, err := client.Complete(context.Background(), req)
+		if err != nil {
+			die(err)
+		}
+		mustWriteJSON(os.Stdout, resp)
+	case "stream":
+		var req llmsdk.Request
+		mustReadJSON(os.Stdin, &req)
+		client, err := llmsdk.DefaultClient()
+		if err != nil {
+			die(err)
+		}
+		es, err := client.Stream(context.Background(), req)
+		if err != nil {
+			die(err)
+		}
+		defer es.Close()
+		w := bufio.NewWriter(os.Stdout)
+		defer w.Flush()
+		for {
+			ev, err := es.Next()
+			if err == io.EOF {
+				break
+			}
+			if err != nil {
+				die(err)
+			}
+			b, _ := json.Marshal(ev)
+			w.Write(b)
+			w.WriteString("\n")
+		}
+	case "tool-call":
+		var req llmsdk.Request
+		mustReadJSON(os.Stdin, &req)
+		// Attach a few simple active tools by name for conformance.
+		for i := range req.Tools {
+			switch req.Tools[i].Name {
+			case "echo":
+				req.Tools[i].Execute = func(ctx llmsdk.ToolContext) (any, error) { return ctx.Arguments, nil }
+			case "add":
+				req.Tools[i].Execute = func(ctx llmsdk.ToolContext) (any, error) {
+					a, _ := asFloat(ctx.Arguments["a"])
+					b, _ := asFloat(ctx.Arguments["b"])
+					return map[string]any{"sum": a + b}, nil
+				}
+			}
+		}
+		res, err := llmsdk.Generate(context.Background(), llmsdk.GenerateParams{Request: req, MaxToolRounds: 5, MaxRetries: 0})
+		if err != nil {
+			die(err)
+		}
+		mustWriteJSON(os.Stdout, res.Response)
+	case "generate-object":
+		var in struct {
+			Request llmsdk.Request   `json:"request"`
+			Schema  json.RawMessage  `json:"schema"`
+		}
+		dec := json.NewDecoder(os.Stdin)
+		if err := dec.Decode(&in); err != nil {
+			die(err)
+		}
+		res, err := llmsdk.GenerateObject(context.Background(), llmsdk.GenerateParams{Request: in.Request, MaxToolRounds: 0, MaxRetries: 0}, in.Schema)
+		if err != nil {
+			die(err)
+		}
+		mustWriteJSON(os.Stdout, res.Output)
+	case "list-models":
+		client, err := llmsdk.DefaultClient()
+		if err != nil {
+			// listing models should work even without env providers
+			mustWriteJSON(os.Stdout, llmsdk.Models)
+			return
+		}
+		mustWriteJSON(os.Stdout, client.ListModels(nil))
+
+	// Tier 2
+	case "session-create":
+		env := agent.NewLocalExecutionEnvironment("")
+		profile := agent.NewOpenAIProfile("", env)
+		sess, err := agent.NewSession(profile, env, nil, nil)
+		if err != nil {
+			die(err)
+		}
+		mustWriteJSON(os.Stdout, map[string]any{"session_id": sess.ID})
+	case "process-input":
+		var in struct {
+			Input    string `json:"input"`
+			Provider string `json:"provider,omitempty"`
+			Model    string `json:"model,omitempty"`
+		}
+		mustReadJSON(os.Stdin, &in)
+		env := agent.NewLocalExecutionEnvironment("")
+		var profile agent.ProviderProfile
+		switch strings.ToLower(in.Provider) {
+		case "anthropic":
+			profile = agent.NewAnthropicProfile(in.Model, env)
+		case "gemini":
+			profile = agent.NewGeminiProfile(in.Model, env)
+		default:
+			profile = agent.NewOpenAIProfile(in.Model, env)
+		}
+		sess, err := agent.NewSession(profile, env, nil, nil)
+		if err != nil {
+			die(err)
+		}
+		res, err := sess.ProcessInput(context.Background(), in.Input)
+		if err != nil {
+			die(err)
+		}
+		mustWriteJSON(os.Stdout, res)
+	case "tool-dispatch":
+		var in struct {
+			Name      string         `json:"name"`
+			ID        string         `json:"id"`
+			Arguments map[string]any `json:"arguments"`
+		}
+		mustReadJSON(os.Stdin, &in)
+		env := agent.NewLocalExecutionEnvironment("")
+		profile := agent.NewOpenAIProfile("", env)
+		cfg := agent.DefaultSessionConfig()
+		dispatcher := &agent.ToolDispatcher{
+			Registry:  profile.ToolRegistry(),
+			Config:    cfg,
+			Env:       env,
+			Emit:      nil,
+			SessionID: "tool-dispatch",
+		}
+		call := llmsdk.ToolCall{ID: in.ID, Name: in.Name, Arguments: in.Arguments}
+		out := dispatcher.ExecuteAll(context.Background(), []llmsdk.ToolCall{call}, true)
+		if len(out) == 0 {
+			die(fmt.Errorf("no result"))
+		}
+		mustWriteJSON(os.Stdout, out[0])
+	case "steering":
+		var in struct {
+			Message string `json:"message"`
+		}
+		mustReadJSON(os.Stdin, &in)
+		_ = in
+		mustWriteJSON(os.Stdout, map[string]any{"ok": true})
+	case "events":
+		env := agent.NewLocalExecutionEnvironment("")
+		profile := agent.NewOpenAIProfile("", env)
+		sess, err := agent.NewSession(profile, env, nil, nil)
+		if err != nil {
+			die(err)
+		}
+		ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
+		defer cancel()
+		go func() { _, _ = sess.ProcessInput(ctx, "Say hello and stop.") }()
+		w := bufio.NewWriter(os.Stdout)
+		defer w.Flush()
+		for ev := range sess.Events() {
+			b, _ := json.Marshal(ev)
+			w.Write(b)
+			w.WriteString("\n")
+			if ev.Kind == agent.EventSessionEnd {
+				return
+			}
+		}
+
+	// Tier 3
+	case "parse":
+		if len(os.Args) < 3 {
+			fmt.Fprintln(os.Stderr, "usage: conformance parse <dotfile>")
+			os.Exit(2)
+		}
+		src, err := os.ReadFile(os.Args[2])
+		if err != nil {
+			die(err)
+		}
+		g, err := attractor.ParseDOT(string(src))
+		if err != nil {
+			die(err)
+		}
+		mustWriteJSON(os.Stdout, g)
+	case "validate":
+		if len(os.Args) < 3 {
+			fmt.Fprintln(os.Stderr, "usage: conformance validate <dotfile>")
+			os.Exit(2)
+		}
+		src, err := os.ReadFile(os.Args[2])
+		if err != nil {
+			die(err)
+		}
+		g, err := attractor.ParseDOT(string(src))
+		if err != nil {
+			die(err)
+		}
+		diags := attractor.Validate(g)
+		// also run transforms to surface stylesheet errors consistently
+		_, _ = attractor.PrepareGraph(g)
+		mustWriteJSON(os.Stdout, diags)
+	case "run":
+		if len(os.Args) < 3 {
+			fmt.Fprintln(os.Stderr, "usage: conformance run <dotfile>")
+			os.Exit(2)
+		}
+		src, err := os.ReadFile(os.Args[2])
+		if err != nil {
+			die(err)
+		}
+		g, err := attractor.ParseDOT(string(src))
+		if err != nil {
+			die(err)
+		}
+		backend := &attractor.AgentBackend{}
+		engine := attractor.NewDefaultEngine(backend, attractor.AutoApproveInterviewer{})
+		res, err := engine.Run(context.Background(), g, attractor.EngineConfig{LogsRoot: "./.attractor_logs"})
+		if err != nil {
+			die(err)
+		}
+		mustWriteJSON(os.Stdout, res)
+	case "list-handlers":
+		backend := &attractor.AgentBackend{}
+		engine := attractor.NewDefaultEngine(backend, attractor.AutoApproveInterviewer{})
+		mustWriteJSON(os.Stdout, engine.Registry.Types())
+	default:
+		fmt.Fprintln(os.Stderr, "unknown subcommand:", cmd)
+		os.Exit(2)
+	}
+}
+
+func mustReadJSON(r io.Reader, v any) {
+	dec := json.NewDecoder(r)
+	dec.UseNumber()
+	if err := dec.Decode(v); err != nil {
+		die(err)
+	}
+}
+
+func mustWriteJSON(w io.Writer, v any) {
+	enc := json.NewEncoder(w)
+	enc.SetEscapeHTML(false)
+	if err := enc.Encode(v); err != nil {
+		die(err)
+	}
+}
+
+func die(err error) {
+	fmt.Fprintln(os.Stderr, err)
+	os.Exit(1)
+}
+
+func asFloat(v any) (float64, bool) {
+	switch t := v.(type) {
+	case float64:
+		return t, true
+	case json.Number:
+		f, err := t.Float64()
+		return f, err == nil
+	default:
+		return 0, false
+	}
+}
+
