+	case "parse":
+		if len(os.Args) < 3 {
+			fmt.Fprintln(os.Stderr, "usage: conformance parse <dotfile>")
+			os.Exit(2)
+		}
+		src, err := os.ReadFile(os.Args[2])
+		if err != nil {
+			die(err)
+		}
+		g, err := attractor.ParseDOT(string(src))
+		if err != nil {
+			die(err)
+		}
+		mustWriteJSON(os.Stdout, g)
+	case "validate":
+		if len(os.Args) < 3 {
+			fmt.Fprintln(os.Stderr, "usage: conformance validate <dotfile>")
+			os.Exit(2)
+		}
+		src, err := os.ReadFile(os.Args[2])
+		if err != nil {
+			die(err)
+		}
+		g, err := attractor.ParseDOT(string(src))
+		if err != nil {
+			die(err)
+		}
+		diags := attractor.Validate(g)
+		// also run transforms to surface stylesheet errors consistently
+		_, _ = attractor.PrepareGraph(g)
+		mustWriteJSON(os.Stdout, diags)
+	case "run":
+		if len(os.Args) < 3 {
+			fmt.Fprintln(os.Stderr, "usage: conformance run <dotfile>")
+			os.Exit(2)
+		}
+		src, err := os.ReadFile(os.Args[2])
+		if err != nil {
+			die(err)
+		}
+		g, err := attractor.ParseDOT(string(src))
+		if err != nil {
+			die(err)
+		}
+		backend := &attractor.AgentBackend{}
+		engine := attractor.NewDefaultEngine(backend, attractor.AutoApproveInterviewer{})
+		res, err := engine.Run(context.Background(), g, attractor.EngineConfig{LogsRoot: "./.attractor_logs"})
+		if err != nil {
+			die(err)
+		}
+		mustWriteJSON(os.Stdout, res)
+	case "list-handlers":
+		backend := &attractor.AgentBackend{}
+		engine := attractor.NewDefaultEngine(backend, attractor.AutoApproveInterviewer{})
+		mustWriteJSON(os.Stdout, engine.Registry.Types())
+	default:
+		fmt.Fprintln(os.Stderr, "unknown subcommand:", cmd)
+		os.Exit(2)
+	}
+}
+
+func mustReadJSON(r io.Reader, v any) {
+	dec := json.NewDecoder(r)
+	dec.UseNumber()
+	if err := dec.Decode(v); err != nil {
+		die(err)
+	}
+}
+
+func mustWriteJSON(w io.Writer, v any) {
+	enc := json.NewEncoder(w)
+	enc.SetEscapeHTML(false)
+	if err := enc.Encode(v); err != nil {
+		die(err)
+	}
+}
+
+func die(err error) {
+	fmt.Fprintln(os.Stderr, err)
+	os.Exit(1)
+}
+
+func asFloat(v any) (float64, bool) {
+	switch t := v.(type) {
+	case float64:
+		return t, true
+	case json.Number:
+		f, err := t.Float64()
+		return f, err == nil
+	default:
+		return 0, false
+	}
+}
+
